COLLDATA("silsila","ur",[[396,"سیدنا زید بن حارثہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”آپ صلی اللہ علیہ وسلم کی طرف وحی کے ابتدائی زمانے میں جبریل آئے اور آپ صلی اللہ علیہ وسلم کو وضو اور نماز کی تعلیم دی، جب وہ وضو سے فارغ ہوئے تو پانی کا ایک چلو لیا اور اسے اپنی شرمگاہ پر چھڑک دیا۔“","",{"t":"سیدنا جبریل نے وضو کی تعلیم دی","k":"أخرجه ابن ماجه: ۱/ ۱۷۲-۱۷۳، والدارقطني: ص ۴۱، والحاكم: ۳/ ۲۱۷، والبيهقي: ۱/ ۱۶۱، وأحمد: ۴/ ۱۶۱\n(الصحيحة: ۸۴۱)","e":"یہ اللہ تعالیٰ کے ہاں وضو اور نماز کی اہمیت ہے کہ صرف وحی پر اکتفا نہیں کیا گیا، بلکہ تعلیم دینے کا بندوبست بھی کیا گیا۔"}],[397,"سیدنا انس رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں تم پر مسواک کے معاملے میں بہت زیادہ تاکید کرتا ہوں۔“","",{"t":"مسواک کی اہمیت","k":"أخرجه البخاري: ۸۸۸، وابن حبان: ۲/ ۲۰۱/ ۱۰۶۳، والدارمي: ۱۷۴، والنسائي: ۱/ ۶، والبيهقي: ۱/ ۳۵، وابن أبي شيبة في ”مصنفه“: ۱/ ۱۷۱، وأحمد: ۳/ ۱۴۳\n(الصحيحة: ۳۹۹۵)"}],[398,"سیدنا عبد اللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”مجھے مسواک کرنے کا (اس قدر زیادہ حکم دیا) کہ میں اپنے دانتوں کے بارے میں ڈرنے لگ گیا۔“","",{"t":"مسواک کی اہمیت","k":"أخرجه الطبراني في ”المعجم الكبير“: ۳/ ۱۵۵/ ۲، وعنه الضياء في ”المختارة“: ۱/ ۲۴۹/ ۶۱\n(الصحيحة: ۱۵۵۶)","e":"دانتوں کے بارے میں ڈرنے کا یہ مفہوم ہے کہ کہیں ایسا نہ ہو کہ وہ اکھڑ جائیں۔"}],[399,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ جب آپ صلی اللہ علیہ وسلم سوتے تو مسواک آپ کے پاس ہوتا، جب بیدار ہوتے تو مسواک سے ابتدا کرتے۔","",{"t":"مسواک کی اہمیت","k":"أخرجه أحمد: ۲/ ۱۱۷، وابن نصر في ”قيام الليل“: ۴۳\n(الصحيحة: ۲۱۱۱)"}],[400,"عبدالرحمن بن ابی لیلیٰ کسی صحابی رسول سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اگر میں اپنی امت پر مشقت نہ سمجھتا تو ان پر مسواک کو یوں فرض قرار دیتا، جیسے وضو کو لازم کیا ہے۔“","",{"t":"مسواک کی اہمیت","k":"أخرجه ابن أبي شيبة في ”المصنف“: ۱/ ۱۷۰، وأخرجه النسائي في ”السنن الكبرى“: ۲/ ۳۶۶/ ۲۹۲۹، والحاكم: ۱/ ۱۴۶، وعنه البيهقي: ۱/ ۳۶ عن ابي هريرة بلفظ: ((لَوْلا أَنْ أَشُقَّ عَلَى أُمَّتِي لَفَرَضْتُ عَلَيْهِمُ السَّوَاكَ مَعَ كُلِّ وُضُوءٍ-))\n(الصحيحة: ۳۰۶۷)","e":"امام صنعانی رحمہ اللہ کہتے ہیں: مسواک کے بارے میں بہت ساری احادیث وارد ہوئی ہیں، مثلا: مسواک انبیا کی سنت ہے، یہ خصائل فطرت میں سے ہے اور جس نماز سے پہلے مسواک کیا جائے، اس کی اس نماز پر ستر گنا فضیلت ہے، جس کے لیے مسواک نہ کیا جائے۔ مسواک کے بارے ایک سو سے زیادہ احادیث مروی ہے، لیکن بڑا تعجب ہے کہ اس سنت کے بارے میں اتنی زیادہ احادیث ہیں، لیکن پھر بھی عوام الناس، بلکہ علما وفقہا کی کثیر تعداد اس سنت سے غافل ہے، یہ بہت بڑی ناکامی ہے۔ (سبل السلام: ۱/ ۸۷)"}],[401,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”نماز تین حصوں پر مشتمل ہے: ایک تہائی حصہ طہارت ہے، ایک تہائی حصہ رکوع ہے اور ایک تہائی حصہ سجدے ہیں۔ جس نے اس کو کما حقہ ادا کیا، اس کی نماز بھی قبول کی جائے گی اور بقیہ اعمال بھی مقبول ہوں گے اور جس کی نماز رد کر دی گئی، اس کے باقی اعمال بھی رد کر دیے جائیں گے۔“","",{"t":"وضو ایک تہائی نماز ہے","k":"أخرجه البزار في ”مسنده“: ۱/ ۱۷۷/ ۳۴۹\n(الصحيحة: ۲۵۳۷)","e":"چونکہ نماز میں طہارت، رکوع اور سجود کو مرکزیت حاصل ہے، اس لیے ان تین امور کا بطورِ خاص ذکر کیا گیا ہے، وگرنہ مزید ایسے ارکان وفرائض موجود ہیں، جن کے معدوم ہونے کی صورت نماز باطل ہو جاتی ہے۔"}],[402,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما کہتے ہیں: میں نے کہا: اے اللہ کے رسول! آپ ڈھانکے ہوئے نئے مٹکے سے وضو کرنا پسند کریں گے، یا لوٹے جیسے دوسرے برتنوں سے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں، بلکہ لوٹے جیسے عام برتنوں میں (وضو کرنا پسند کروں گا)۔ بیشک اللہ تعالیٰ کا دین آسان ہے۔ ملت اسلام، نرمی و سہولت آمیز شریعت پر مشتمل ہے۔“ آپ صلی اللہ علیہ وسلم مطاہر کے لیے بھیجتے تھے، پس پانی لایا جاتا تھا، آپ صلی اللہ علیہ وسلم پیتے تھے اور مسلمانوں کے ہاتھوں کی برکت کی امید کرتے تھے۔","",{"t":"آپ صلی اللہ علیہ وسلم عام برتنوں کے ساتھ وضو کر لیتے","k":"أخرجه الطبراني في ”الأوسط“: ۳۵، وأبو نعيم في ”الحلية“: ۸/ ۲۰۳\n(الصحيحة: ۲۱۱۸)","e":"”مطاہر“ سے مراد وہ برتن ہیں، جن سے طہارت حاصل کی جاتی ہے، مثلا لوٹا، ڈونگا، بالٹی وغیرہ۔"}],[403,"عبدالرحمن بن جبیر بن نفیر اپنے باپ سے روایت کرتے ہیں کہ سیدنا ابو جبیر رضی اللہ عنہ اپنی بیٹی کے ہمراہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، جس سے آپ صلی اللہ علیہ وسلم نے شادی کی تھی۔ آپ صلی اللہ علیہ وسلم نے ان کے لیے وضو کے پانی کا حکم دیا اور فرمایا: ”ابو جبیر! وضو کرو۔“ ابو جبیر نے منہ سے (وضو کرنا) شروع کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کو فرمایا: ”منہ سے شروع نہ کرو، کیونکہ کافر منہ سے شروع کرتا ہے۔“ پھر رسول اللہ صلی اللہ علیہ وسلم نے وضو کا پانی منگوایا (اور اس ترتیب سے وضو کیا)، ہتھیلیاں دھوئیں، حتی کہ ان کو صاف کیا، تین بار کلی کی اور ناک میں پانی چڑھایا، تین دفعہ چہرہ دھویا، تین بار کہنی تک دایاں بازو دھویا اور پھر تین دفعہ بایاں، پھر سر کا مسح کیا اور دونوں پاؤں دھوئے۔","",{"t":"وضو کا طریقہ","k":"أخرجه ابن حبان في ”صحيحه“: ۱۴۸، والدولابي في ”الأسماء والكنى“: ۱/ ۲۳، وأبو أحمد الحاكم في ”الكنى“: ق ۲/ ۶۱، والبيهقي في ”السنن الكبرى“: ۱/ ۴۶، وابن عساكر في ”تاريخ دمشق“: ۱۷/ ۱/ ۳۱۵\n(الصحيحة: ۲۸۲۰)"}],[404,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ آپ صلی اللہ علیہ وسلم جب وضو کرتے تو پانی کو اپنی کہنیوں پر گھماتے۔","",{"t":"وضو کا طریقہ","k":"أخرجه الدارقطني في ”سننه“: ۳۱، والبيهقي: ۱/ ۵۶\n(الصحيحة: ۲۰۶۷)"}],[405,"سیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ آپ صلی اللہ علیہ وسلم کبھی وضو میں ایک ایک دفعہ (اعضا دھوتے)، کبھی دو دو دفعہ اور کبھی تین تین دفعہ۔ ان میں سے ہر طریقہ اپناتے تھے۔","",{"t":"وضو کا طریقہ","k":"قال الهيثمي: ۱/ ۲۳۳ رواه الطبراني في ”الكبير“\n(الصحيحة: ۲۱۲۲)","e":"یہ شریعت کی طرف سے رخصت ہے، پانی کی قلت کے پیش نظر یا عمدا صرف ایک مرتبہ اعضا دھو لینے سے وضو مکمل ہو جاتا ہے۔ البتہ دو دو مرتبہ اعضا دھونا ایک ایک مرتبہ اعضا کے دھونے سے زیادہ بہتر ہے، بلکہ اس سے دوہرا اجر ملتا ہے اور تین تین مرتبہ اعضا دھونا سابقہ دونوں صورتوں سے افضل، اعلیٰ اور بہتر ہے۔ جس طرح کہ حدیث مبارکہ میں صراحت کے ساتھ اس کی فضیلت کا بیان آ رہا ہے۔"}],[406,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے وضو کا پانی منگوایا اور اپنا چہرہ، دونوں ہاتھ اور دونوں پاؤں ایک ایک دفعہ دھوئے اور فرمایا: ”یہ وضو ہے کہ جس کے بغیر اللہ تعالیٰ نماز قبول نہیں کرتے۔“ پھر آپ صلی اللہ علیہ وسلم نے پانی منگوایا، دو دو بار (اعضا) دھوئے اور فرمایا: ”یہ وضو ہے، کہ جو آدمی ایسا وضو کرے گا، اللہ تعالیٰ اس کو دو گنا اجر عطا کرے گا۔“ پھر آپ صلی اللہ علیہ وسلم نے پانی منگوایا، تین تین بار (اعضا) دھوئے اور فرمایا: ”یہ تمہارے نبی اور اس سے پہلے والے انبیا کا وضو ہے۔ یا فرمایا: ”یہ میرا وضو ہے اور مجھ سے قبل انبیا کا وضو رہا ہے۔“","",{"t":"وضو کا طریقہ","k":"رواه ابن شاهين في ”الترغيب“: ۱/ ۲۶۲-۲، وابن السكن في ”صحيحه“\n(الصحيحة: ۲۶۱)"}],[407,"عمرو بن شعیب اپنے باپ سے اور وہ ان کے دادا سیدنا عبد اللہ بن عمرو رضی اللہ عنہ سے روایت کرتے ہیں، وہ کہتے ہیں: ایک بدو نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور وضو کے بارے میں سوال کیا۔ آپ صلی اللہ علیہ وسلم نے اسے وضو کر کے دکھایا، جس میں تین تین دفعہ (اعضا دھوئے)، پھر فرمایا: ”وضو اس طرح کیا جاتا ہے، جو اس (مقدار) سے زیادہ دفعہ (اعضا) دھوتا ہے، وہ برا کرتا ہے، زیادتی کرتا ہے اور ظلم کرتا ہے۔“","",{"t":"وضو کا طریقہ","k":"أخرجه النسائي: ۱/ ۳۳، وابن ماجه: ۱/ ۱۶۳-۱۶۴\n(الصحيحة: ۲۹۸۰)","e":"درج بالا اور دوسری احادیث صحیحہ سے وضو کے ثابت ہونے والے احکام: وضو کا مسنون طریقہ: ابتدا میں بسم اللہ پڑھنا، تین دفعہ ہاتھ دھونا اور انگلیوں کا خلال کرنا، تین دفعہ کلی کرنا اور ناک میں پانی چڑھانا اور یہ دونوں کام صرف ایک چلو سے کرنا، تین دفعہ چہرہ دھونا اور داڑھی کا خلال کرنا، تین دفعہ دایاں اور پھر بایاں بازو کہنیوں سمیت دھونا، سر اور کانوں کا ایک چلو پانی سے مسح کرنا، پھر تین دفعہ دایاں اور تین دفعہ بایاں پاؤں دھونا اور انگلیوں کا خلال کرنا، وضو کے بعد ایک چلو پانی شرمگاہ پر چھڑکنا اور مسنون دعائیں پڑھنا۔ ملحوظات: تین دفعہ اعضا دھونا افضل ہے، اگر تمام اعضا ایک ایک یا دو دو بار دھوئے جائیں یا ایک وضو کے دوران کوئی عضو ایک دفعہ کوئی دو دفعہ اور کوئی تین دفعہ دھویا جائے تو وضو درست ہو گا۔ کلی کرتے وقت منہ میں پانی کو حرکت دی جائے اور سانس کے ذریعے ناک میں پانی چڑھا کر اسے سانس کے پریشر کے ذریعے باہر نکالا جائے، اور یہ دونوں کام ایک چلو پانی سے کیے جائیں، یعنی آدھے چلو سے کلی کی جائے اور آدھے سے ناک کی صفائی۔ سر پر مسح کرنے کے تین طریقے ہیں مکمل سر پر، مکمل پگڑی پر اور سر کے اگلے حصے پر اور باقی پگڑی پر۔ سر کا مسح تین دفعہ کرنا بھی درست ہے۔ گردن اور اس کے پہلوؤں پر مسح کرنے کی کوئی قابل حجت دلیل نہیں ہے۔ جس حدیث میں وضو کے بعد انگلی اٹھانے کا ذکر ہے، وہ ضعیف ہے اور آسمان کی طرف دیکھنا بھی کسی صحیح حدیث سے ثابت نہیں ہے۔"}],[408,"سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم، سیدنا سعد رضی اللہ عنہ کے پاس سے گزرے، وہ وضو کر رہے تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”سعد! یہ کیا اسراف ہے؟“ سعد رضی اللہ عنہ نے کہا: کیا وضو میں بھی اسراف ہوتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جی ہاں، اگر چہ تو جاری نہر پر بھی ہو۔“","",{"t":"وضو میں بھی اسراف ہوسکتا ہے؟","k":"أخرجه الأمام أحمد: ۲/ ۲۲۱، وابن ماجه: ۴۲۵\n(الصحيحة: ۳۲۹۲)","e":"اعضائے وضو کو زیادہ سے زیادہ تین دفعہ دھونے کا حکم ہے، اس حد سے تجاوز کرنے والا برا کرتا ہے، زیادتی کرتا ہے اور ظلم کرتا ہے، جیسا کہ نسائی اور ابن ماجہ کی روایت میں ہے۔"}],[409,"سیدنا زید بن حارثہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”آپ صلی اللہ علیہ وسلم کی طرف وحی کے ابتدائی زمانے میں جبریل آئے اور آپ صلی اللہ علیہ وسلم کو وضو اور نماز کی تعلیم دی، جب وہ وضو سے فارغ ہوئے تو پانی کا ایک چلو لیا اور اسے اپنی شرمگاہ پر چھڑک دیا۔“","",{"t":"وضو کے بعد پانی کا ایک چلو شرمگاہ پر چھڑکنا","k":"أخرجه ابن ماجه: ۱/ ۱۷۲-۱۷۳، والدارقطني: ص ۴۱، والحاكم: ۳/ ۲۱۷، والبيهقي: ۱/ ۱۶۱، وأحمد: ۴/ ۱۶۱\n(الصحيحة: ۸۴۱)","e":"سنن ابی داؤد، ابن ماجہ اور نسائی وغیرہ کی دیگر روایات میں صحابہ کرام رضی اللہ عنہم نے رسول اللہ صلی اللہ علیہ وسلم سے صراحت کے ساتھ وضو کے بعد چھینٹے مارنے کا معمول نقل کیا ہے۔ اس لیے وضو کے بعد اس کا اہتمام کرنا چاہیے۔"}],[410,"سیدنا خالد بن ولید، سیدنا یزید بن ابی سفیان، سیدنا شرحبیل بن حسنہ اور سیدنا عمرو بن عاص رضی اللہ عنہم سے روایت ہے کہ انھوں نے نبی کریم صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”وضو کو مکمل کیا کرو، (وضو میں خشک رہ جانے والی) ایڑھیوں کے لیے آگ سے ہلاکت ہے۔“","",{"t":"نامکمل وضو باعث ہلاکت ہے","k":"أخرجه ابن ماجه: ۱/ ۱۷۰\n(الصحيحة: ۸۷۲)","e":"اس حدیث طیبہ سے واضح ہوا کہ وضو میں پاؤں دھونا فرض ہے۔ بعض لوگ وضو میں پاؤں پر مسح کرتے ہیں جو کہ قطعاً درست نہیں، اگر قرآنی آیت کی حقیقی تفسیر نبی کریم صلی اللہ علیہ وسلم کے اقوال و افعال کی روشنی میں کی جائے تو یہ بات بالکل عیاں ہوتی ہے کہ پاؤں پر مسح نہیں بلکہ پاؤں کو اچھی طرح دھونا فرض ہے۔ بصورت دیگر وضو نہیں ہوگا اور متعلقہ شخص ہلاکت کی وعید کا حقدار ٹھہرے گا۔ ہاں جب موزے پہنے ہوئے ہوں تو کچھ شرائط کے ساتھ مسح کیا جا سکتا ہے۔"}],[411,"سیدنا عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم طہارت والے پانی کے ساتھ انگلیوں کو مبالغہ کے ساتھ دھوؤ گے، (وگرنہ) آگ ان کو خوب جلائے گی۔“","",{"t":"نامکمل وضو باعث ہلاکت ہے","k":"أخرجه الطبراني في ”المعجم الأوسط“: ۳/ ۱۲۲/ ۲۶۷۴\n(الصحيحة: ۳۴۸۹)","e":"اعضائے وضو کو اچھے انداز میں دھویا جائے تا کہ کوئی حصہ خشک نہ رہ جائے۔"}],[412,"سیدنا عبد اللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تو وضو کرے تو ہاتھ اور پاؤں کی انگلیوں میں خلال کیا کر۔“","",{"t":"دوران وضو انگلیوں کا خلال کرنا","k":"أخرجه الترمذي: ۱/ ۱۰، والحاكم: ۱/ ۱۸۲، وأحمد: ۱/ ۲۸۷\n(الصحيحة: ۱۳۰۶)"}],[413,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”بہت خوب ہیں میری امت کے وہ لوگ، جو خلال کرتے ہیں۔“","",{"t":"دوران وضو انگلیوں کا خلال کرنا","k":"أخرجه الطبراني في ”الأوسط“: ۱/ ۳۹- مصورة الجامعة الأسلامية\n(الصحيحة: ۲۵۶۷)"}],[414,"سیدنا عبد اللہ بن عباس رضی اللہ عنہما کہتے ہیں: ایک آدمی نے نبی کریم صلی اللہ علیہ وسلم سے نماز کے بارے میں کوئی سوال کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ہاتھوں اور پاؤں کی انگلیوں کا خلال کرو“ آپ کی مراد یہ تھی کہ وضو مکمل کیا جائے۔ مزید آپ صلی اللہ علیہ وسلم نے اسے یہ بھی فرمایا تھا: ”جب تو رکوع کرے تو اپنی ہتھیلیوں کو گھٹنوں پر رکھ کر (رکوع کی حالت میں) مطمئن ہو جا اور جب تو سجدہ کرے تو اپنی پیشانی کو اچھی طرح زمین پر رکھ، حتی کہ تو زمین کی ضخامت پائے۔“","",{"t":"دوران وضو انگلیوں کا خلال کرنا","k":"أخرجه أحمد: ۱/ ۲۸۷\n(الصحيحة: ۱۳۴۹)","e":"اس میں دوران وضو ہاتھوں اور پاؤں کی انگلیوں میں خلال کرنے کا حکم دینے کے ساتھ ساتھ اطمینان کے ساتھ نماز پڑھنے کی تلقین کی گئی ہے۔ آخری جملے کا مفہوم یہ ہے کہ دورانِ سجدہ پیشانی کا زمین پر زور آنا چاہیے اور وہ اس طرح ممکن ہو گا کہ سنت کے مطابق بازوؤں کو پہلوؤں سے اچھی طرح جدا کیا جائے، تا کہ ناک اور پیشانی زمین پر اچھی طرح ٹک سکیں۔"}],[415,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے یہ سوال کیا گیا: اے اللہ کے رسول! آپ کا اس آدمی کے بارے میں کیا خیال ہے، جو بے وضو ہو جاتا ہے، پھر وضو کرتا ہے اور موزوں پر مسح کرتا ہے، تو کیا وہ نماز پڑھ سکتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ایسا کرنے میں کوئی حرج نہیں۔“","",{"t":"موزوں پر مسح کی مدت اور مزید احکام جرابوں پر مسح کرنا","k":"أخرجه ابن حبان في ”صحيحه“: ۱۷۲- موارد\n(الصحيحة: ۲۹۴۰)"}],[416,"سیدنا عقبہ بن عامر جہنی رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں: میں جمعہ کے روز شام سے مدینہ کی طرف نکلا، (وہاں پہنچ کر) میں سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس گیا۔ انھوں نے کہا: تو نے اپنے پاؤں میں موزے کب پہنے تھے؟ میں نے کہا: جمعہ کے دن۔ انھوں نے کہا: کیا ان کو بعد میں اتارا بھی ہے؟ میں نے کہا: نہیں۔ انھوں نے فرمایا: تو نے سنت کی موافقت کی ہے۔","",{"t":"موزوں پر مسح کی مدت اور مزید احکام جرابوں پر مسح کرنا","k":"أخرجه الطحاوى في ”شرح المعاني“: ۱/ ۴۸، والدارقطني في ”السنن“: ص ۷۲، والحاكم: ۱/ ۱۸۰-۱۸۱، وعنه البيهقي في ”السنن“: ۱/ ۲۸۰\n(الصحيحة: ۲۶۲۲)","e":"موزوں پر مسح کرنے سے متعلقہ احکام یہ ہیں: وضو کر کے موزے پہنے جائیں۔ مقیم کو مکمل ایک دن یعنی چوبیس گھنٹے اور مسافر کو تین دنوں تک مسح کرنے کی سہولت دی گئی ہے، اگر کوئی مجبوری ہو تو مسافر سات دنوں تک لگاتار مسح کر سکتا ہے۔ پیشاب، پاخانہ، نیند اور دوسرے نواقض وضو سے جب وضو ٹوٹ جاتا ہے تو مسح کی مدت پر کوئی فرق نہیں پڑتا اور نہ موزوں کو اتارنا پڑتا ہے، لیکن جب جنابت کا غسل فرض ہو جائے تو موزے اتار کر وضو اور غسل کرنا ضروری ہے۔ مسح کرتے وقت صرف پاؤں کے ظاہری حصے پر ہاتھ پھیرا جائے۔ جرابوں کا بھی یہی حکم ہے۔ امام البانی رحمہ اللہ رقمطراز ہیں: ایسے لگتا ہے کہ امام بیہقی اور امام نووی وغیرہ نے بھی اس حدیث کو صحیح کہا، کیونکہ انھوں نے مسح کے تین ایام کے تعین پر دلالت کرنے والی احادیث کے تعارض میں اس حدیث کو ذکر کیا اور ضعیف نہیں کہا ..... (موزوں پر مسح کرنے کے بارے میں متعارض قسم کی روایات مروی ہیں، ایک حدیث کے مطابق مقیم ایک دن تک اور مسافر تین دنوں تک مسح کر سکتا ہے، جبکہ اس حدیث سے ثابت ہوتا ہے کہ مسافر کو سات ایام تک مسح کرنے کی رخصت ہے۔) ان دو احادیث میں اس طرح جمع وتطبیق ممکن ہے کہ سات دنوں والی روایت کو ضرورت اور جماعت کی معیت میں رہنے کی وجہ سے موزے نہ اتار سکنے پر محمول کیا جائے، شیخ الاسلام امام ابن تیمیہ رحمہ اللہ کا بھی یہی خیال ہے ..... (صحیحه: ۲۶۲۲)"}],[417,"سیدنا خزیمہ بن ثابت انصاری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”موزوں پر تین دنوں تک مسح کرو“، اور اگر ہم نے زیادہ (دنوں) کا مطالبہ کیا ہوتا تو آپ صلی اللہ علیہ وسلم ہمیں مزید (دنوں کی) رخصت دے دیتے۔","",{"t":"موزوں پر مسح کی مدت اور مزید احکام جرابوں پر مسح کرنا","k":"أخرجه أحمد: ۵/ ۲۱۳، والطبراني في ”المعجم الكبير“: رقم- ۳۷۵۵، وابن حبان: ۱۸۳\n(الصحيحة: ۱۵۵۹)"}],[418,"عبدالرحمن بن ابوبکرہ اپنے باپ سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے مسافر کو تین دنوں اور راتوں تک اور مقیم کو ایک دن اور رات تک موزوں پر مسح کرنے کی رخصت دی، (لیکن شرط یہ ہے کہ) اس نے باوضو ہو کر موزے پہنے ہوں۔","",{"t":"موزوں پر مسح کی مدت اور مزید احکام","k":"أخرجه ابن خزيمة في ”صحيحه“: ۱/ ۹۶/ ۱۹۲، والطحاوي في ”شرح المعاني“: ۱/ ۵۰، والدارقطني في ”سننه“: ۱/ ۱/ ۱۹۴، وابن عبدالبر في ”التمهيد“: ۱۱/ ۱۵۵- والسياق لهم، والشافعي في ”الأم“: ۱/ ۲۹، وابن أبي شيبة في ”المصنف“: ۱/ ۱۷۹، وابن الجارود في ”المنتقى“: ۳۹/ ۸۷، وابن حبان: ۷۲/ ۱۸۴- الموارد وابن ماجه: ۵۵۶، والبيهقي في ”سننه“: ۱/ ۲۸۱\n(الصحيحة: ۳۴۵۵)"}],[419,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب کوئی آدمی اپنے پاؤں میں موزے پہنے، اس حال کہ اس کے (پاؤں وضو کی وجہ سے) پاک ہوں، تو ان پر مسح کر لیا کرے، مسافر تین دنوں تک کر سکتا ہے اور مقیم ایک دن رات تک۔“","",{"t":"موزوں پر مسح کی مدت اور مزید احکام","k":"رواه ابن أبي شيبة في ”المصنف“: ۱/ ۱۲۳\n(الصحيحة: ۱۲۰۱)","e":"اب ہم جرابوں پر مسح کرنے کے دلائل ذکر کرتے ہیں: (۱) سیدنا ثوبان رضی اللہ عنہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ایک جماعت کو باہر بھیجا، انھیں سفر میں سردی لگی، جب وہ واپس آئے اور نبی کریم صلی اللہ علیہ وسلم سے سردی کی شکایت کی تو فَأَمَرَهُمْ أَنْ يَمْسَحُوا عَلَى الْعَصَائِبِ وَالتَّسَاخِينِ ..... آپ صلی اللہ علیہ وسلم نے ان کو حکم دیا کہ وہ پگڑیوں اور ”تساخین“ پر مسح کر لیا کریں۔ (احمد: ۵/ ۲۷۷، ابوداود: ۱۴۶) ”تساخین“ کے معانی ہیں: گرمی پہنچانے والی چیز، وہ چمڑے کا موزہ ہو یا سوتی یا اونی جرابیں۔ امام ابن ارسلان رحمہ اللہ نے کہا: اصل ذالك كُلُّ مَا يُسْخَنُ بِهِ الْقَدَمُ مِنْ حُفٍّ وَجَوْرَبٍ وَنَحْوِهِمَا ..... ”تساخین“ ہر اس چیز کو کہتے ہیں جس سے پاؤں کو سردی سے بچایا جائے، وہ موزہ ہو یا جراب وغیرہ۔ (عون المعبود: ۱/ ۵۶) (۲) سیدنا بلال رضی اللہ عنہ کہتے ہیں: كَانَ رَسُولَ اللهِ صلى الله عليه وسلم يَمْسَحُ عَلَى الْخُفَّيْنِ وَالْجَوْرَبَيْنِ ...... نبی کریم صلی اللہ علیہ وسلم موزوں اور جرابوں پر مسح کیا کرتے تھے۔ (معجم کبیر للطبرانی: ۱/ ۳۵۰) اس کی سند یزید بن ابی زیاد کی وجہ سے ”ضعیف“ ہے، لیکن اس کے متعدد شواہد موجود ہیں۔ (۳) سیدنا ابوموسی اشعری رضی اللہ عنہ بیان کرتے ہیں: إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم تَوَضَّأَ وَمَسَحَ عَلَى الْجَوْرَبَيْنِ وَالنَّعْلَيْنِ ..... نبی کریم صلی اللہ علیہ وسلم نے وضو کیا اور جرابوں اور جوتیوں پر مسح کیا۔ (ابن ماجہ: ۵۶۰، بیہقی: ۱/ ۲۸۵) اس حدیث کی سند میں انقطاع ہے اور عیسی بن سنان ضعیف ہے، لیکن اس کے شواہد موجود ہیں۔ (۴) سیدنا ابو موسی اشعری رضی اللہ عنہ ہی بیان کرتے ہیں: آتَيْتَ رَسُولَ اللَّهِ صلى الله عليه وسلم بَوَضُوءٍ فَمَسَحَ عَلَى الْجَوْرَبَيْنِ وَالنَّعْلَيْنِ وَالْعَمَامَةِ ..... ”میں آپ صلی اللہ علیہ وسلم کے پاس وضو کا پانی لے کر آیا، آپ صلی اللہ علیہ وسلم نے جرابوں اور جوتیوں اور پگڑی پر مسح کیا۔ (معجم اوسط للطبرانی: ۲/ ۶۶) (۵) سیدنا مغیرہ بن شعبہ رضی اللہ عنہ کہتے ہیں: تَوَضَّأَ النَّبِيُّ صلى الله عليه وسلم وَمَسَحَ عَلَى الْجَوْرَبَيْنِ وَالنَّعْلَيْنِ ..... نبی کریم صلی اللہ علیہ وسلم نے وضو کیا اور جرابوں اور جوتیوں پر مسح کیا۔ (ترمذی: ۹۹، ابوداود: ۱۵۹) اس کی سند میں سفیان ثوری مدلس ہے، لیکن دوسرے شواہد کی بنا پر یہ حدیث صحیح ہے۔ البتہ ابن ترکمانی حنفی (متوفی: ۸۴۵ھ) کے نزدیک یہ حدیث صحیح ہے۔ دیکھیں: الجوہر النقی: ۱/ ۲۸۴) کعب بن عبد اللہ کہتے ہیں: میں نے دیکھا کہ سیدنا علی رضی اللہ عنہ نے پیشاب کیا، پھر اپنی جرابوں اور جوتیوں پر مسح کیا۔ (الاوسط لابن المنذر: ۱/ ۴۶۲، المحلى لابن حزم: ۲/ ۸۴) سیدنا عمر بن خطاب رضی اللہ عنہ نے جوتیوں کے تسموں سمیت جرابوں پر مسح کیا۔ (تھذیب السنن لابن القیم: ۱/ ۲۷۵) امام ابوداود رحمہ اللہ نے کہا: سیدنا علی بن ابو طالب، سیدنا عبد اللہ بن مسعود، سیدنا برا بن عازب، سیدنا انس بن مالک، سیدنا ابوامامہ، سیدنا سہل بن سعد اور سیدنا عمرو بن حریث رضی اللہ عنہم جرابوں پر مسح کرتے تھے، اور سیدنا عمر بن خطاب اور سیدنا عبد اللہ بن عباس رضی اللہ عنہما سے بھی یہی عمل مروی ہے۔ (ابو داؤد) جرابوں پر مسح کے بارے میں صحابہ کا اجماع و اتفاق ہے، دیکھیں: (المغنی لابن قدامہ: ۱/ ۱۸۱، الاوسط لابن المنذر: ۱/ ۴۶۴، المحلى لابن حزم: ۲/ ۸۷) امام ترمذی رحمہ اللہ کہتے ہیں: میں نے صالح بن محمد ترمذی رحمہ اللہ سے سنا، وہ کہتے تھے کہ میں نے ابو مقاتل سمرقندی سے سنا، وہ کہتے تھے کہ میں امام ابو حنیفہ رحمہ اللہ کے ہاں حاضر ہوا، وہ مرض الموت میں مبتلا تھے، انھوں نے پانی منگوایا اور وضو کیا اور جرابوں پر مسح کیا اور کہا: میں نے آج ایسا کام کیا ہے جو پہلے نہ کرتا تھا، میں نے غیر منقل جرابوں پر مسح کیا ہے۔ (جامع ترمذی: ۹۹) تفصیل کے لیے دیکھیں: جامع ترمذی از علامہ احمد محمد شاکر: ۱/ ۱۶۷) فقہ حنفی میں ”قیاس“ پر بہت زور دیا جاتا ہے، اس مسئلہ میں قیاس کا یہی تقاضا تھا کہ جرابوں پر مسح کرنے کے جواز کو تسلیم کیا جاتا، کیونکہ موزوں اور جرابوں کی علت ایک ہے۔"}],[420,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں سے کوئی آدمی نیند سے بیدار ہو اور وضو کرے تو ناک تین دفعہ جھاڑے، کیونکہ شیطان اُس کی ناک کی جڑ میں رات گزارتا ہے۔“","",{"t":"بیداری کے بعد وضو کرتے وقت تین دفعہ ناک جھاڑنا","k":"أخرجه البخاري: ۳۲۹۵- فتح، ومسلم: ۱/ ۱۴۶، وأبو عوانة: ۱/ ۲۴۸، والنسائي: ۱/ ۲۷، وابن خزيمة في ”صحيحه“: ۱/ ۷۷/ ۱۴۹، والبيهقي: ۱/ ۴۹، وأحمد: ۲/ ۳۵۲\n(الصحيحة: ۳۹۶۱)","e":"ویسے تو وضو کے اعضا کو ایک یا دو یا تین دفعہ دھونا درست ہے، لیکن نیند کے بعد کیے جانے والے وضو میں ناک کو تین دفعہ پانی سے جھاڑا جائے، تاکہ شیطان کا اثر ختم ہو جائے۔ عربی لفظ ”استنثار“ (ناک جھاڑنے) سے مراد یہ ہے کہ آدمی چلو میں پانی لے کر سانس کے ذریعے ناک میں چڑھائے، پھر اس کو سانس کے پریشر کے ساتھ ناک سے خارج کرے۔ یہ معنی نہیں کہ ایک دفعہ ہاتھ سے ناک میں پانی دھکیل کر اس کو بہا دیا جائے اور پھر بائیں ہاتھ سے اسے تین دفعہ جھاڑ دیا جائے اور پھر دو دفعہ پانی بہا دیا جائے، جیسا کہ ہمارے ہاں اکثر لوگ کرتے ہیں۔ احادیث سے یہ ثابت ہوتا ہے کہ سانس کے ذریعے چلو سے پانی ناک کی جڑ تک کھینچا جائے، پھر اسے سانس کے پریشر کے ساتھ نکال دیا جائے، یہ ایک بار ہوگی۔"}],[421,"نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”دونوں کان سر میں سے ہیں۔“ یہ الفاظ سیدنا ابو امامہ، سیدنا ابو ہریرہ، سیدنا عبد اللہ بن عمرو، سیدنا عبد اللہ بن عباس، سیدہ عائشہ، سیدنا ابو موسیٰ، سیدنا انس، سیدنا سمرہ بن جندب اور سیدنا عبداللہ بن زید رضی اللہ عنہم کی حدیث سے روایت کیے گئے ہیں۔","",{"t":"کان سر کا ہی حصہ ہیں","k":"۱- أما حديث أبي أمامه فرواه أبو داود والترمذي وابن ماجه، وابن جرير: ۶/ ۷۶، والدارقطني، والبيهقى، وكذا أحمد: ۵/ ۲۸۵/ ۲۶۸، والطحاوي، والدارقطنی: ص ۸۳-۹۳ ۲- وأما حديث أبي هريرة فأخرجه الدارقطني: ص ۳۷/ ۳۸، وعنه ابن الجوزي في ”التحقيق“: ۱/ ۲۹/ ۱، وأبو يعلى في ”مسنده“: ۱/ ۲۹۸ ۳- وأما حديث ابن عمر قال المخلص في ”الفوائد المنتقاة“ فى الثانى من السادس منها: ق ۱/ ۱۹۰: حدثنا يحيى ..... وبهذا السند رواه الدارقطني: ۳۶، وعنه ابن الجوزي، ورواه الخطيب في ”الموضح“: ۱/ ۱۱، عن ابن صاعد، وفي ”التاريخ“: ۱۴/ ۱۶۱ ۴- وأما حديث ابن عباس؛ فأخرجه ابن عدی: ۱/ ۲۱۸-۲، وأبو عبدالله الفلاكي في ”الفوائد“: ۱/ ۹۱، والدارقطني: ۳۶، ورواه الطبراني في ”المعجم الكبير“: ۱۰/ ۳۹۱/ ۱۰۴۸ ۵- وأما حديث عائشة؛ فأخرجه الدارقطنی: ص ۳۷ ۶- حديث أبي موسى؛ فأخرجه الطبراني في ”الأوسط“: ۱/ ۴/ ۱- من زوائده، وابن عدی: ۱/ ۲۳، والدارقطنی: ۳۸ ۷- وأما حديث أنس؛ فأخرجه ابن عدى: ۱/ ۲۴، وأبو الحسن الحمامي في ”الفوائد المنتقاة“: ۲/ ۱/ ۹، والدارقطنی: ۳۹ ۸- وأما حديث سمرة بن جندب فرواه تمام الرازي في ”مسند المقلين من الأمراء والسلاطين“: ۳- نسختي، وعنه ابن عساكر في ”تاريخه“: ۱۴/ ۱/ ۳۸۷ ۹- وأما حديث عبدالله؛ فأخرجه ابن ماجه: ۴۴۳\n(الصحيحة: ۳۶)","e":"اس حدیث سے دو مسائل پر روشنی پڑتی ہے: (۱) کانوں کے مسح کو وہی حکم ہے، جو سر کا ہے، کیونکہ کان سر کا حصہ ہیں، اور (۲) جو پانی سر کا مسح کرنے کے لیے لیا، وہی کانوں کے مسح کے لیے کافی ہے، کیونکہ وہ سر کا حصہ ہیں۔ امام البانی رحمہ اللہ رقمطراز ہیں: یہ حدیث دو مختلف فیہ فقہی مسائل پر دلالت کرتی ہے: (اول) ..... کیا کانوں کا مسح کرنا فرض ہے یا سنت؟ حنابلہ کا خیال ہے کہ فرض ہے، ان کی دلیل یہی حدیث ہے، کیونکہ اس میں یہ صراحت کی گئی ہے کہ کان سر کا حصہ ہیں، اور یہ صرف اس بنا پر کہا گیا ہے کہ کانوں کے لیے مسح کا وہی حکم ہے، جو سر کے لیے ہے۔ لیکن جمہور کا خیال ہے کہ کانوں کا مسح سنت ہے، جیسا کہ (الفقه على المذاهب الاربعة: ۱/ ۵۶) میں ہے، لیکن اس حدیث کے مقابلے میں جمہور کے پاس کوئی ایسی دلیل نہیں ہے، جس پر ان کے استدلال کی بنیاد رکھی جائے۔ البتہ امام نووی رحمہ اللہ نے (المجموع: ۱/ ۴۱۵) میں یہ دعوی کیا ہے کہ اس حدیث کے تمام طرق ضعیف ہیں۔ لیکن یہ دعوی درست نہیں ہے، کیونکہ اس حدیث کے بعض طرق صحیح اور بعض صحیح لغیرہ ہیں، لیکن امام نووی کو ان کا علم نہ ہوسکا۔ اس حدیث کی روشنی میں یہ کہنا درست ہوگا کہ کانوں کا مسح سر کے مسح کی طرح واجب ہے، امام احمد بن حنبل کا بھی یہی مسلک ہے، بلکہ ان سے پہلے صحابہ کی ایک جماعت اس کے وجوب کا اعتراف کر چکی ہے، تخریج کے دوران بعض کے نام بھی ذکر کیے گئے ہیں، امام نووی رحمہ اللہ (۱/ ۴۱۳) نے خود وجوب کو کئی سلف کی طرف منسوب کیا ہے۔ (دوم) ..... کیا کانوں کے مسح کے لیے سر کے مسح سے بچا ہوا پانی ہی کافی ہے یا نیا پانی لینا ضروری ہے؟ ائمہ ثلاثہ کی رائے یہ ہے کہ سر کے مسح سے بچا ہوا پانی کافی ہے، مناوی رحمہ اللہ نے (فیض القدیر) میں اس حدیث کی شرح کرتے ہوئے کہا: ”دونوں کان سر میں سے ہیں۔“ (اس حدیث کا مطلب یہ ہے کہ کانوں کو) نہ چہرے کا حکم دیا جائے گا اور نہ ان کا کوئی مستقل حکم ہے۔ اس لیے دوران وضو سر کے مسح سے بچا ہوا پانی ہی ان کے مسح کے لیے کافی ہے، نیا پانی لینے کی ضرورت نہیں۔ ائمہ ثلاثہ کا بھی یہی مسلک ہے۔ اگر اس حدیث کا یہ مفہوم مراد نہ لیا جائے تو اس کا مطلب ہوگا کہ آپ صلی اللہ علیہ وسلم انسان کی کوئی پیدائشی ہیئت بیان کر رہے، جو کہ آپ صلی اللہ علیہ وسلم کی بعثت کا مقصود نہیں ہے۔ شافعیہ کا خیال ہے کہ کانوں کے لیے نیا پانی لینا اور ان کا الگ حیثیت سے مسح کرنا سنت ہے، واجب نہیں ہے، امام نووی رحمہ اللہ نے ان کے حق میں یہ حدیث پیش کی ہے کہ سیدنا عبد اللہ بن زید رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کانوں کے لیے نیا پانی لیا، یہ اس پانی کے علاوہ تھا جو آپ صلی اللہ علیہ وسلم نے سر کے لیے لیا تھا۔ امام نووی رحمہ اللہ نے (المجموع: ۱/ ۴۱۲) میں کہا: یہ حدیث حسن ہے، امام بیہقی رحمہ اللہ نے اس کو روایت کیا اور کہا کہ اس کی سند صحیح ہے۔ امام نووی رحمہ اللہ (۱/ ۴۱۴) نے مزید کہا: یہ حدیث صحیح ہے، جیسا کہ اس کی وضاحت ہو چکی ہے، اس سے واضح طور پر یہ پتہ چلتا ہے کہ کان سر سے نہیں ہیں، اگر وہ سر سے ہوتے تو آپ صلی اللہ علیہ وسلم ان کے لیے نیا پانی نہ لیتے، جیسا کہ دوسرے اعضا کا مسئلہ ہے، لیکن اس حدیث میں یہ صراحت موجود ہے کہ آپ صلی اللہ علیہ وسلم نے کانوں کے لیے نیا پانی لیا۔ میں (البانی) کہتا ہوں: اگر فرض کر لیں کہ سیدنا عبد اللہ بن زید رضی اللہ عنہ کی حدیث صحیح ہے تو امام نووی رحمہ اللہ وغیرہ نے اپنی رائے کے حق میں جو کچھ کہا، اس سے ان کا دعوی ثابت نہیں ہوتا، کیونکہ ان کی دلیل یعنی سیدنا عبد اللہ بن زید رضی اللہ عنہ کی حدیث سے یہ ثابت ہوتا ہے کہ آپ صلی اللہ علیہ وسلم نے کانوں کے لیے نیا پانی لیا۔ اس کا یہ معنی تو نہیں بنتا کہ سر سے بچے ہوئے پانی پر اکتفا کرنا جائز نہیں ہے، جیسا کہ اس باب کی حدیث سے ثابت ہوتا ہے۔ حقیقت یہ ہے کہ یہ دونوں احادیث متفق ہیں، ان کا آپس میں کوئی تعارض نہیں۔ ہمارے دعوی کی تائید درج ذیل روایت سے بھی ہوتی ہے: آپ صلی اللہ علیہ وسلم نے سر کا مسح اس پانی سے کیا جو (بازؤوں کو دھونے کے بعد) ہاتھوں میں بچا ہوا تھا۔ (رواہ ابو داود في سننه بسند حسن، و له شاهد عن ابن عباس في المستدرك بسند حسن انظر: التخليص الحبير) جبکہ حقیقت یہ ہے کہ سیدنا عبد اللہ بن زید کی یہ حدیث شاذ ہے، (جس کو امام نووی نے حسن اور صحیح کہا ہے)۔ میں نے (صحيح أبي داود: ۱۱۱) اور (سلسلة الأحاديث الضعيفة: ۹۹۷) میں اس کی تفصیل بیان کی ہے۔ خلاصہ کلام یہ ہے کہ امام احمد بن حنبل کا مسلک راجح ہے، انھوں نے اس باب کی حدیث سے ثابت ہونے والے دونوں مسائل کو حرز جان بنایا۔ (صحیحه: ۳۶)"}],[422,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”جو آدمی باوضو رات گزارتا ہے (یعنی وضو کر کے سوتا ہے)، ایک فرشتہ اس کے تختانی لباس میں رات گزارتا ہے، جب بھی وہ بندہ رات کی کسی گھڑی میں بیدار ہوتا ہے تو وہ فرشتہ کہتا ہے: اے اللہ! اپنے فلاں بندے کو بخش دے، کیونکہ اس نے باوضو حالت میں رات گزاری۔“","",{"t":"رات کو باوضو سونے کی فضیلت","k":"أخرجه عبدالله بن المبارك في ”حديثه“: ۲/ ۱۰/ ۲، وفي ”الزهد“: ق ۲۱۶/ ۱ و رقم ۱۲۴۴- ط، وابن عدی: ق ۱/ ۸۹، وابن حبان: ۱۶۷- موارد، وابن شاهين في ”الترغيب“: ق ۲/ ۳۱۳\n(الصحيحة: ۲۵۳۹)","e":"نیک اعمال کی برکات کا اندازہ لگائیں کہ سو جانے کے بعد وضو برقرار نہیں رہتا، لیکن اس کے اچھے اثرات باقی رہتے ہیں۔"}],[423,"سیدنا عروہ رضی اللہ عنہ سے روایت ہے کہ آپ صلی اللہ علیہ وسلم کے پاس کپڑے کا ایک ٹکڑا تھا، جس سے وضو کے بعد (اعضا) خشک کرتے تھے۔","",{"t":"وضو کے بعد تولیہ استعمال کرنا","k":"وله طريقان: (۱) عن عائشة: أخرجه الترمذي: ۱/ ۷۴، وابن عدى: ۱/ ۱۵۴، والحاكم: ۱/ ۱۵۴، والبيهقي: ۱/ ۱۸۵ (۲) عن ابى بكر الصديق: اخرجه ابن عليك النيسابورى فى ”الفوائد“: ۱/ ۲۳۹، والبيهقى\n(الصحيحة: ۲۰۹۹)","e":"وضو کے بعد اعضائے وضو کو تولیے وغیرہ سے خشک کرنے یا نہ کرنے کا وضو کے اجر کی کمی یا زیادتی کے ساتھ کوئی تعلق نہیں ہے۔"}],[424,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”غسل ایک صاع سے اور وضو ایک مڈ سے ہوسکتا ہے۔“","",{"t":"غسل اور وضو کے لیے پانی کی مقدار","k":"رواه الطبراني في ”الأوسط“: ۳۶۱۱، وابن عدي: ۲/ ۶۹\n(الصحيحة: ۱۹۹۱)","e":"وضو کرتے ہوئے بلا ضرورت پانی ضائع نہیں کرنا چاہیے، اگر انسان جاری نہر پر بھی بیٹھا وضو کر رہا ہو تو وہاں بھی بقدر ضرورت ہی پانی استعمال کرنا چاہیے، دیکھیں ”وضو میں بھی اسراف ہوسکتا ہے“ والی سرخی۔ صاع ایک پیمانے کا نام ہے، تقریبا اس میں ڈالی گئی چیز کا وزن دو کلو سو گرام ہوتا ہے اور ایک صاع میں چار مڈ ہوتے ہیں۔"}],[425,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”وضو کے لیے پانی کا ایک مڈ اور غسل کے لیے ایک صاع کافی ہے۔“ یہ حدیث سیدنا عقیل بن ابو طالب، سیدنا جابر بن عبد اللہ، سیدنا انس بن مالک اور سیدنا عبداللہ بن عباس رضی اللہ عنہم سے مروی ہے۔","",{"t":"غسل اور وضو کے لیے پانی کی مقدار","k":"(۱) - أما حديث عقيل: أخرجه ابن ماجه: ۲۷۰ (۲) - وأما حديث جابر: أخرجه الحاكم: ۱/ ۱۶۱ (۳) - وأما حديث أنس: أخرجه أحمد: ۳/ ۱۷۹، والترمذى: ۲/ ۵۰۷/ ۶۰۹ بلفظ: يجزى في الوضوء رطلان من ماء (۴) - وأما حديث ابن عباس أخرجه الطبراني في ”الأوسط“: ص ۳۷\n(الصحيحة: ۲۴۴۷)"}],[426,"سیدنا ثوبان رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”راہ صواب پر چلو، میانہ روی اختیار کرو، عمل کرو اور (بہترین امور کو) ترجیح دو اور جان لو کہ تمہارا سب سے بہترین عمل نماز ہے اور مومن ہی ہے، جو وضو پر محافظت کرتا ہے۔“","",{"t":"وضو کی حفاظت مومن ہی کرتا ہے","k":"رواه الامام أحمد: ۵/ ۲۸۲ والدارمي: ۱/ ۱۶۸، وابن حبان: ۱۶۴، والطبراني في ”المعجم الكبير“: ۱/ ۷۲/ ۲\n(الصحيحة: ۱۱۵)","e":"ہمیشہ باوضو رہنے والے ہی بتلا سکتے ہیں کہ اس عمل میں کس قدر روحانی تسکین پائی جاتی ہے۔"}],[427,"سیدنا حذیفہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بیشک میرے حوض (کی وسعت) ایلہ سے عدن تک کی مسافت سے زیادہ ہے، اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! اس کے پیالے ستاروں کی تعداد سے زیادہ ہیں، (اس کا پانی) دودھ سے زیادہ سفید اور شہد سے زیادہ میٹھا ہے۔ اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! میں کچھ لوگوں کو اپنے حوض سے یوں دھتکاروں گا، جیسے کوئی آدمی اجنبی اونٹ کو اپنے حوض سے ہٹاتا ہے۔“ کہا گیا: اے اللہ تعالیٰ کے رسول! کیا آپ ہم کو پہچان لیں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جی ہاں، تم میرے پاس اس حال میں آؤ گے کہ وضو کے اثر کی وجہ سے تمہاری پیشانی، دونوں ہاتھ اور دونوں پاؤں چمکتے ہوں گے، یہ علامت (ومنقبت) کسی اور کی نہیں ہوگی۔“","",{"t":"آپ صلی اللہ علیہ وسلم کی امت کے وضو والے اعضا چمکتے ہوں گے وضو والے اعضا کو مقررہ حد سے زیادہ دھونا کیسا ہے؟","k":"أخرجه مسلم: ۱/ ۱۵۰، وابن ماجه: ۴۳۰۲\n(الصحيحة: ۳۵۲۶)","e":"اس میں آپ صلی اللہ علیہ وسلم کے حوض، اس کی صفات اور آپ صلی اللہ علیہ وسلم کی امتیوں کی مخصوص علامت کا ذکر ہے، جس کی وجہ سے وہ تمام دوسرے انبیا کی امتوں سے ممتاز نظر آئیں گے۔ اس سے ہمیں سبق یہ ملتا ہے کہ ہم ان احکام کی پیروی کریں، جن سے وضو کرنا پڑتا ہے، تا کہ اس سعادت تک پہنچ سکیں۔ دوسری روایات میں وضاحت ہے کہ بدعتی لوگوں کو حوض محمدی سے دور دھتکار دیا جائے گا، اس لیے ہمیں آپ صلی اللہ علیہ وسلم کی سنتوں کی پیروی کا حریص ہونا چاہیے۔"}],[428,"ابو حازم کہتے ہیں: میں سیدنا ابو ہریرہ رضی اللہ عنہ کے پیچھے تھا، انھوں نے نماز کے لیے وضو کیا، (بازو دھوتے وقت) اپنے ہاتھ کو بغلوں تک کھینچا۔ میں نے کہا: ابو ہریرہ! یہ کون سا وضو ہے؟ انھوں نے کہا: بنوفروخ! تم بھی ادھر موجود ہو؟ اگر مجھے معلوم ہوتا کہ تم لوگ یہاں ہو تو میں اس طرح وضو نہ کرتا۔ میں نے تو اپنے خلیل صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: ”مومن کا زیور وہاں تک پہنچتا ہے، جہاں تک وضو (کا پانی) پہنچتا ہے۔“","",{"t":"آپ صلی اللہ علیہ وسلم کی امت کے وضو والے اعضا چمکتے ہوں گے وضو والے اعضا کو مقررہ حد سے زیادہ دھونا کیسا ہے؟","k":"أخرجه مسلم: ۱/ ۱۵۱، وأبو عوانة: ۱/ ۲۴۴، والنسائي: ۱/ ۳۵، والبيهقي: ۱/ ۵۶، وأحمد: ۲/ ۳۷۱، وابن أبي شيبة في ”المصنف“: ۱/ ۴۰\n(الصحيحة: ۲۵۲)","e":"امام البانی رحمہ اللہ کہتے ہیں: کیا یہ حدیث اس بات پر دلالت کرتی ہے کہ مزید فضیلت کے حصول کے لیے وضو کے دوران بازؤوں کو کندھوں کی طرف کہنیوں سے آگے تک اور پاؤں کو پنڈلی کی طرف ٹخنوں سے آگے تک دھویا جائے، اسی طرح چہرے کے ساتھ دوسرے اعضا کو بھی ملایا جائے، مثلا گردن کے پہلو؟ اگر ہم سیدنا ابو ہریرہ رضی اللہ عنہ کی رائے کا اعتبار نہ کریں تو یہ حدیث مبارکہ اعضا کو ان کی مقررہ حد سے زیادہ دھونے پر دلالت نہیں کرتی، کیونکہ آپ صلی اللہ علیہ وسلم کے فرمان کا تعلق شرعی وضو سے ہے، (جس کا کم از کم اور زیادہ سے زیادہ طریقہ مقرر ہو چکا ہے)۔ اگر شریعت میں اعضا کو ان کی حد سے بڑھ کر دھونا ثابت نہیں ہوتا، تو ظاہر بات ہے کہ یہ عمل صحیح نہیں ہوگا۔ یہ حدیث کہنی سے بازو کے پچھلے حصے کو دھونے پر دلالت نہیں کرتی کیونکہ وہ ”غُرَّۃ“ اور ”تَحْجِیل“ میں داخل ہی نہیں ہے، اسی لیے ابن قیم رحمہ اللہ نے (حادي الأرواح ألى بلاد الأفراح: ۱/ ۳۱۵-۳۱۶) میں کہا: ”جو لوگ کہنی کے بعد کا بازو کا حصہ دھونے کے قائل ہیں، انھوں نے اس حدیث سے استدلال کیا ہے، لیکن حقیقت یہ ہے کہ ایسا کرنا مستحب نہیں ہے، یہی اہل مدینہ کی رائے ہے، البتہ امام احمد سے دو روایتیں منقول ہیں۔ بہر حال یہ حدیث اعضا کو ان کی مقررہ حد سے بڑھ کر دھونے پر دلالت نہیں کرتی، کیونکہ زیور کلائی اور کہنی تک کے بازو کے کچھ حصے میں ہوتا ہے، نہ کہ کہنی کے بعد والے بازو کے حصے اور کندھے میں۔“ زائد حصے کو دھونے کے قائلین کی دوسری دلیل یہ ہے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «إِنَّ أُمَّتِي يَأْتُونَ يَوْمَ الْقِيَامَةِ غُرًّا مُحَجَّلِينَ مِنْ آثَارِ الْوُضُوءِ- فَمَنِ اسْتَطَاعَ مِنْكُمْ أَنْ يُطِيلَ غُرَّتَهُ فَلْيَفْعَلْ-» (بخاری، مسلم) ..... ”میری امت کے لوگوں کو قیامت والے دن اس حال میں پکارا جائے گا کہ وضو کے نشانات سے ان کے چہرے اور ہاتھ پاؤں روشن ہوں گے، پس تم میں سے جو شخص اپنی یہ روشنی بڑھانے کی طاقت رکھے تو وہ ضرور ایسا کرے۔“ لیکن اس حدیث کا آخری جملہ ”فَمَنِ اسْتَطَاعَ مِنْكُمْ أَنْ يُطِيلَ غُرَّتَهُ فَلْيَفْعَلْ“ مرفوع حدیث کے الفاظ نہیں ہیں، بلکہ سیدنا ابو ہریرہ رضی اللہ عنہ کا اپنا قول ہے، جیسا کہ امام منذری، امام ابن تیمیہ، امام ابن قیم اور حافظ ابن حجر عسقلانی رحمہم اللہ وغیرہ نے اس کے مدرج ہونے کی صراحت کی ہے، میں نے (سلسلة الاحاديث الضعيفة: ۱۰۳۰) میں اس کی خوب وضاحت کی ہے، اگر یہ جملہ صحیح ہوتا تو اعضائے وضو کو ان کی حد سے بڑھ کر دھونے پر واضح نص ہوتا۔ والله ولي التوفيق۔ (صحیحه: ۲۵۲) خلاصہ کلام یہ ہے کہ سیدنا ابو ہریرہ رضی اللہ عنہ کا کہنیوں سے آگے والے کندھے کی طرف کے حصے کو دھونا ان کی اپنی رائے اور جذبہ تھا۔"}],[429,"سیدنا عبد اللہ بن بسر مازنی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں اپنی امت کے ہر فرد کو قیامت والے دن پہچان لوں گا۔“ صحابہ نے عرض کی: اے اللہ کے رسول! آپ انھیں کیسے پہچانیں گے، حالانکہ مخلوقات بکثرت ہوں گی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اگر تو کسی اصطبل میں داخل ہو اور وہاں کالے سیاہ گھوڑے ہوں، لیکن ان میں ایک گھوڑے کی پیشانی اور ٹانگیں سفید ہوں تو آیا آپ اس گھوڑے کو پہچان لیں گے؟“ اس نے کہا: کیوں نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”تو پھر سجدہ کرنے کی وجہ سے میری امت کی پیشانی اور وضو کرنے کی وجہ سے ہاتھ پاؤں چمکتے ہوں گے (اس امتیازی علامت کی وجہ سے میں انھیں پہچان لوں گا)۔“","",{"t":"آپ صلی اللہ علیہ وسلم کی امت کے وضو والے اعضا چمکتے ہوں گے","k":"أخرجه أحمد: ۴/ ۱۸۹، والضياء المقدسي في ”المختارة“: ۱/ ۱۱۴/ ۵۵-۲، والطبراني في ”الكبير“ والبيهقي في ”الشعب“\n(الصحيحة: ۲۸۳۶)","e":"تمام روایات کو دیکھا جائے تو چہرے پر چمک کے دو اسباب ہیں، ایک، وضو میں چہرے کو دھونا اور دوسرا، سجدہ کرنا۔"}],[430,"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں: سیدنا ابوذر رضی اللہ عنہ ربذہ مقام پر اپنی بکریوں میں تھے۔ جب وہ واپس آئے تو نبی کریم صلی اللہ علیہ وسلم نے ان کو آواز دیتے ہوئے فرمایا: ”ابو ذر!“، لیکن وہ خاموش رہے، آپ صلی اللہ علیہ وسلم نے بار بار آواز دی، لیکن وہ خاموش رہے، بالآخر آپ صلی اللہ علیہ وسلم نے فرمایا: ”ابوذر! تیری ماں تجھے گم پائے۔“ اب کی بار انھوں نے کہا: میں جنبی ہوں۔ پس آپ صلی اللہ علیہ وسلم نے ایک لونڈی کو پانی لانے کا حکم دیا۔ جب وہ پانی لے کر آئی تو انھوں نے اپنی سواری کی اوٹ میں پردہ کر کے غسل کیا اور پھر آپ صلی اللہ علیہ وسلم کے پاس آ گئے، آپ صلی اللہ علیہ وسلم نے ان کو فرمایا: ”(ایسی صورت میں) تجھے مٹی کافی ہے، اگر چہ بیس سال یا دس سال پانی نہ ملے، جب تو پانی پالے تو اسے اپنے چمڑے کے ساتھ لگائے، (یعنی غسل کرے)۔“","",{"t":"تیمم کا دنوں کی مقدار کے ساتھ تعلق نہیں ہے","k":"أخرجه الطبراني في ”المعجم الأوسط“: ۲/ ۱۹۸/ ۱۳۵۵- ط، وأخرج البزار في ”مسنده“: ۱/ ۱۵۷/ ۳۱۰ المرفوع منه\n(الصحيحة: ۳۰۲۹)","b":"اس حدیث سے معلوم ہوا کہ تیمم کے تعلق مجبوری سے ہے، نہ کہ دنوں کی مخصوص مقدار سے۔"}],[431,"سیدنا عمار بن یاسر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تیمم کے بارے میں فرمایا: ”چہرے اور ہتھیلیوں کے لیے ایک دفعہ ہاتھوں کو (مٹی پر مارا جائے)۔“","",{"t":"تیمم کا طریقہ","k":"أخرجه ابن خزيمة في ”صحيحه“: ۲/ ۳۸، وأحمد: ۴/ ۲۶۳، ومعناه في الصحيحين وابي داود\n(الصحيحة: ۶۹۴)","e":"پانی کے نقصان دہ ہونے یا پانی کے نہ ہونے یا پانی کے استعمال پر قادر نہ ہونے کی صورت میں شریعت اسلامیہ نے تیمم کی رخصت دی ہے، نمازی لوگوں کی بہت بڑی پریشانی کا ازالہ کر دیا۔ تیمم کا سب سے بہترین طریقہ یہ ہے کہ بسم اللہ پڑھ کر دونوں ہاتھوں کو مٹی پر مارا جائے، پھر ان پر پھونک ماری جائے، پھر دائیں ہاتھ کو بائیں پر اور بائیں کو دائیں پر پھیر کر دونوں ہاتھوں کو چہرے پر پھیر دیا جائے۔ ہاتھوں کو صرف ایک دوسرے کی ہتھیلی کی پشت پر پھیرا جائے گا، نہ کہ کہنیوں تک۔ تیمم ان امور سے ختم ہو جاتا ہے، جن سے وضو ٹوٹ جاتا ہے، ہاں ایک چیز زائد ہے کہ پانی نظر آنے کی صورت میں یا پانی کے استعمال پر قدرت حاصل ہو جانے کی صورت میں تیمم ٹوٹ جاتا ہے۔ صحیح احادیث سے تیمم کے لیے زمین پر ایک دفعہ ہاتھ مارنا ثابت ہے۔ جن احادیث سے دو بار ہاتھ مارنا ثابت ہوتا ہے، وہ یا تو ضعیف ہیں یا پھر موقوف۔"}],[432,"سیدنا عبد اللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ آپ صلی اللہ علیہ وسلم پیشاب کرتے اور مٹی سے استنجا کر لیتے تھے۔ میں نے کہا: اے اللہ کے رسول! بیشک پانی آپ کے قریب ہی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”مجھے کیا علم، شاید میں وہاں تک نہ پہنچ سکوں۔“","",{"t":"پانی تک پہنچنے سے پہلے تیمّم کرنا اور اس کی وجہ","k":"أخرجه عبد الله بن المبارك في ”الزهد“: ۲۹۲، وأحمد: ۱/ ۲۸۸\n(الصحيحة: ۲۶۲۹)","e":"حدیث اپنے مضمون میں واضح ہے کہ مومن کو ہر وقت طہارت کا خیال رکھنا چاہیے، اگر پانی کی موجودگی یقینی ہو، لیکن دور ہو، تو وہاں تک پہنچنے سے پہلے تیمم کر لینا چاہیے۔"}],[433,"سیدنا سلمان رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”زمین کو چھو اکرو، کیونکہ یہ تمہارے ساتھ شفقت کرنے والی ہے۔“","",{"t":"مٹی سے تیمم کرنے یا اس پر سجدہ کرنے کا حکم اور وجہ","k":"رواه أبو الشيخ في ”تاريخ أصبهان“: ص ۲۳۸، والطبراني في ”المعجم الصغير“: ۸۳\n(الصحيحة: ۱۷۹۲)","e":"امام البانی رحمہ اللہ کہتے ہیں: امام ابن ابی شیبہ رحمہ اللہ نے اس حدیث کو مرسلا ”کتاب التیمم“ میں ذکر کیا، گویا کہ وہ یہ اشارہ دینا چاہتے ہیں کہ «تَمَسَّحُوا» کے معانی تیمم کرنے کے ہیں۔ اسی معنی کو ابن اثیر نے راجح قرار دیا، وہ کہتے ہیں: آپ صلی اللہ علیہ وسلم اس حدیث میں مٹی سے تیمم کرنے کا حکم دینا چاہتے ہیں، اور یہ بھی کہا گیا ہے کہ آپ صلی اللہ علیہ وسلم کا مقصود یہ ہے کہ سجدہ بغیر کسی حائل کے زمین پر کیا جائے، تا کہ پیشانیاں مٹی پر لگ سکیں، ہاں یہ بات ضرور ہے کہ یہ حکم تادبی اور استحبابی ہے، وجوبی نہیں ہے۔ «بَرَّةٌ» کا معنی ہے کہ یہ زمین تمہارے ساتھ اس طرح شفقت کرنے والی ہے، جیسے ماں اپنی اولاد کے ساتھ کرتی ہے، یعنی تم لوگوں کی تخلیق بھی اسی سے ہوئی، تمہاری روزی کے اسباب بھی اسی میں ہیں، مرنے کے بعد تمہاری لوٹنے کی جگہ بھی یہی ہے۔ خلاصہ یہ ہے کہ یہ اصل ہے اور تم اس کی فرع ہو، (یہ تم کو ہر چیز مہیا کر رہی ہے)۔"}],[434,"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ سیدہ خولہ بنت یسار رضی اللہ عنہا نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور کہا: اے اللہ کے رسول! میرے پاس صرف ایک کپڑا ہے، اس میں مجھے حیض بھی آ جاتا ہے، تو اس کے بارے میں مجھے کیا کرنا چاہیے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جب تو پاک ہو جائے تو اس کو دھو لیا کر اور اس میں نماز پڑھا کر۔“ اس نے کہا: اگر اس میں سے خون نہ نکلے تو؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”بس تجھے پانی ہی کافی ہے اور اس کا نشان تجھے نقصان نہیں دے گا۔“","",{"t":"مٹی سے تیمم کرنے یا اس پر سجدہ کرنے کا حکم اور وجہ","k":"أخرجه أبو داود: ۱/ ۱۴۱-۱۴۲، بشرح العون، وأحمد: ۲/ ۳۸۰، والبيهقي في ”السنن“: ۲/ ۴۰۸، والترمذي\n(الصحيحة: ۲۹۸)"}],[435,"سیدہ اسماء بنت ابوبکر رضی اللہ عنہما سے روایت ہے، وہ کہتی ہیں کہ ایک عورت نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا اور کہا: اگر ہم میں سے کسی کے کپڑے پر حیض کا خون لگ جائے، تو وہ (اس کو پاک کرنے کے لیے) کیا کرے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں سے کسی کے کپڑے کو حیض کا خون لگ جائے تو وہ (پانی کے ساتھ) اس کو ملے، پھر اس پر پانی ڈال کر (اس کو دھو لے)۔“ اور ایک روایت میں ہے: ”اس کو پانی کے ساتھ مل، پھر باقی ماندہ پر پانی ڈال کر (اس کو دھو لے)، پھر اس میں نماز پڑھ لے۔“","",{"t":"حیض والے کپڑے کو کیسے پاک کیا جائے؟","k":"أخرجه مالك: ۱/ ۷۹، وعنه البخاري: ۱/ ۳۲۵، ومسلم: ۱/ ۱۶۶، وأبو داود: ج ۳/ رقم: ۳۸۶- صحيحه، والبيهقي: ۱/ ۱۳، والنسائي: ۱/ ۶۹، وابوداود الطيالسي: ۱۶۳۸، وابن ماجه: ۱/ ۲۱۷، واحمد: ۶/ ۳۴۵، ۳۵۳، والترمذي: ۱/ ۲۵۴\n(الصحيحة: ۲۹۹)","e":"حیض کا خون نجس ہے۔ کپڑے پر لگا ہو تو اُس میں نماز پڑھنا درست نہیں ہے، اُس جگہ کو اچھی طرح کھرچتے ہوئے دھو لینا چاہیے، اگر کھرچنے، ملنے اور دھونے کے بعد خون کی رنگت یا خون کا نشان کپڑے پر باقی رہے تو یہ قابلِ مواخذہ نہیں، اُس میں نماز پڑھنا درست ہوگی۔"}],[436,"سیدہ ام قیس بنت محصن رضی اللہ عنہا کہتی ہیں: میں نے نبی کریم صلی اللہ علیہ وسلم سے حیض کے خون کے بارے میں سوال کیا، جو کپڑے کو لگ جاتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”کسی شاخ (وغیرہ) کے ساتھ اس کو کھرچ، پھر پانی اور بیری کے پتوں کے ساتھ دھو دے۔“","",{"t":"حیض والے کپڑے کو کیسے پاک کیا جائے؟","k":"أخرجه أبو داود: ۱/ ۱۴۱ -بشرح عون المعبود، والنسائي: ۱/ ۱۶۹، والدارمي: ۱/ ۲۲۹، وابن ماجه: ۱/ ۲۱۷، وابن حبان في ”صحيحه“: ۲۳۵، والبيهقي: ۲/ ۴۰۷، وأحمد: ۶/ ۳۵۵، ۳۵۶\n(الصحيحة: ۳۰۰)","e":"بیری کے پتوں والے پانی سے دھونے کا مقصود اچھی طرح صفائی وطہارت حاصل کرنا ہے اور بیری کے پتوں میں یہ خاصیت ہے کہ وہ میل کچیل کو اچھی طرح صاف کر دیتے ہیں۔ اگر آج کل کسی پاؤڈر اور صابن وغیرہ کے ذریعے مکمل صفائی ہو جائے تو درست ہے، جیسا کہ ہو رہا ہے، بہر حال کبھی کبھی محض آپ صلی اللہ علیہ وسلم کے حکم کی تعمیل کرتے ہوئے بیری کے پتوں کا اہتمام بھی ہو جانا چاہیے، جیسے ہم میت کو غسل دینے کے موقع پر کرتے ہیں۔"}],[437,"زوجہ رسول سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی لونڈی یا آپ کے غلام ابورافع کی بیوی نے آپ صلی اللہ علیہ وسلم کے پاس ابورافع کی شکایت کرنے کی اجازت چاہی، جس نے اسے مارا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے ابورافع سے پوچھا: ”ابورافع! تیرا اور اس کا کیا معاملہ ہے؟“ اس نے کہا: اے اللہ کے رسول! یہ مجھے تکلیف دیتی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”سلمیٰ! تو نے اس کو کیا تکلیف دی ہے؟“ اس نے کہا: اے اللہ کے رسول! میں نے اس کو کوئی تکلیف نہیں دی، (اصل بات یہ ہے کہ) نماز کی حالت میں یہ بے وضو ہو گیا، میں نے اسے کہا: ابورافع! رسول اللہ صلی اللہ علیہ وسلم نے مسلمانوں کو حکم دیا ہے کہ اگر کسی کی ہوا نکل جائے تو وہ وضو کرے۔ طبرانی کے الفاظ یہ ہیں: بیشک رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس کی ہوا خارج ہو جائے تو وہ دوبارہ وضو کرے۔“ (میری یہ بات سن کر) یہ اٹھا اور مجھے مارنا شروع کر دیا۔ رسول اللہ صلی اللہ علیہ وسلم اس کی بات پر مسکرانے لگے اور فرمایا: ”ابورافع! اس نے تجھے بھلائی کا ہی حکم دیا تھا۔“","",{"t":"نواقض وضو","k":"أخرجه أحمد: ۶/ ۷۷، والبزار: ۱/ ۱۴۶/ ۲۸۰، والطبراني في ”المعجم الكبير“: ۲۴/ ۳۰۱/ ۷۶۵\n(الصحيحة: ۳۰۷)","e":"یہ بھی معلوم ہوا کہ بیوی کی اچھی بات پر اس کو سرزنش نہ کی جائے، بلکہ خندہ پیشانی سے اس کی طرف سے کلمہ خیر قبول کرتے ہوئے اس کی حوصلہ افزائی کی جائے۔ اچھا شوہر اپنی اہلیہ کی اچھی باتوں کو اپنے لیے سرمایہ ہدایت سمجھتا ہے۔ خاوند حضرات کو اتنا جذباتی بھی نہیں ہونا چاہیے کہ وہ اپنی بیویوں کی ہر بات، وہ اچھی ہو یا بری، پر مسئلہ کھڑا کر دیں۔"}],[438,"سیدہ بسرہ بن صفوان رضی اللہ عنہا سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”جب کوئی آدمی اپنی شرمگاہ کو اپنا ہاتھ لگائے، تو وہ وضو کرے۔“","",{"t":"نواقض وضو","k":"أخرجه النسائي: ۱/ ۷۶، واحمد: ۶/ ۴۰۷، والحاكم: ۱/ ۱۳۶\n(الصحيحة: ۱۲۳۵)","e":"آلہ تناسل کو چھونے کو ”مسّ الذکر“ کہتے ہیں، ہم بحث میں یہی لفظ استعمال کریں گے۔ اسی طرح سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «مَنْ أَفْضَى بِيَدِهِ إِلَى ذَكَرِهِ لَيْسَ دُونَهُ سِتْرٌ فَقَدْ وَجَبَ عَلَيْهِ الْوُضُوءُ-» ...... ”جو شخص اپنے آلہ تناسل کو بغیر کسی پردے کے چھوئے تو اس پر وضو واجب ہے۔“ (مسند احمد: ۲/ ۳۳۳، طحاوی: ۱/ ۷۴) اور مسند شافعی (۱/ ۳۳) کے الفاظ یہ ہیں: «إِذَا أَفْضَى أَحَدُكُمْ إِلَى ذَكَرِهِ لَيْسَ بَيْنَهَا وَبَيْنَهُ شَيْءٌ فَلْيَتَوَضَّأْ-» لیکن ان دو روایات کے مقابلے میں درج ذیل حدیث پر غور کریں: سیدنا طلق بن علی رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے کہا: اے اللہ کے نبی! اس شخص کے بارے میں آپ کا کیا خیال ہے، جس نے وضو کرنے کے بعد اپنے آلہ تناسل کو چھولیا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: «هَلْ هُوَ إِلَّا بَضْعَةٌ مِنْهُ» ..... ”(تو پھر کیا ہوا) وہ اس کے جسم کا ٹکڑا ہی ہے۔“ ان روایات کی بنیاد پر سلف وخلف میں اختلاف واقع ہوا ہے کہ آیا ”مسّ الذکر“ ناقض وضو ہے یا نہیں۔ راجح یہی معلوم ہوتا کہ وضو ٹوٹ جاتا ہے، بشرطیکہ چھونے کی صورت یہ ہو کہ ہاتھ اور شرمگاہ میں کوئی پردہ حائل نہ ہو، جیسا کہ سیدنا بسرہ اور سیدنا ابوہریرہ رضی اللہ عنہما کی روایات کے الفاظ سے معلوم ہو رہا ہے۔ لیکن سیدنا طلق کی روایت کا کیا جائے گا؟ محدثین نے جمع وتطبیق کے چند طریقے مقرر کیے ہیں، ان سب کی روشنی میں سیدنا بسرہ کی روایت پر عمل کیا جائے گا، مثال کے طور پر: (۱) سیدنا طلق کی روایت کا تعلق اس صورت سے ہے، جب ہاتھ اور شرمگاہ کے درمیان پردہ حائل ہو، یہی تطبیق مناسب نظر آرہی ہے، اس طرح سے دونوں روایات پر عمل کرنا ممکن ہو جائے گا۔ (۲) اگر اسانید کو دیکھا تو سیدنا بسرہ کی روایت راجح قرار پاتی ہے۔ (۳) اگر احتیاط کے معاملے کو سامنے رکھا تو سیدنا بسرہ کی روایت پر عمل کرنا چاہیے۔ (۴) اگر اباحت اور خطر میں تعارض پیدا ہو جائے تو خطر کو مقدم کیا جاتا ہے، جو کہ سیدنا بسرہ کی روایت ہے۔ (۵) اگر متعارض امور میں سے ایک کا تعلق براءتِ اصلیہ سے ہو تو اسے منسوخ سمجھا جائے گا، اس اعتبار سے بھی سیدنا بسرہ کی حدیث ناسخ اور قابلِ عمل قرار پاتی ہے۔ (۶) ایک تطبیق یہ بھی دی گئی ہے کہ اگر شہوت کے ساتھ چھوا جائے تو وضو ٹوٹ جائے گا، وگرنہ نہیں۔ خلاصہ کلام یہ ہے کہ سیدنا بسرہ رضی اللہ عنہا کی حدیث پر عمل کرتے ہوئے ”مسّ الذکر“ کو ناقض وضو سمجھیں گے۔ والله اعلم۔ تنبیہ ..... اس سلسلے میں مرد اور عورت کی قبل اور دبر یعنی اگلی اور پچھلی شرمگاہ میں کوئی فرق نہیں ہے، جیسا کہ سیدہ ام حبیبہ رضی اللہ عنہا کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «مَنْ مَسَّ فَرْجَهُ فَلْيَتَوَضَّأْ-» ...... ”جو اپنی فرج کو چھوئے، وہ وضو کرے۔“ لفظ ”فرج“ کا اطلاق مرد اور عورت کی دونوں شرمگاہوں پر ہوتا ہے۔ (ابن ماجہ: ۴۸۱) اسی طرح سیدنا عبد اللہ بن عمرو بن عاص رضی اللہ عنہما کی روایت میں مرد اور عورت کا علیحدہ علیحدہ تذکرہ کیا گیا ہے، اس کو امام احمد اور امام دارقطنی نے روایت کیا۔ احادیث صحیحہ کی روشنی میں نواقض وضو درج ذیل ہیں: (۱) پیشاب اور پاخانہ کے مقام سے کوئی چیز خارج ہونا (۲) سو جانا، وہ جس حالت میں بھی ہو (۳) شرمگاہ کو چھونا، جبکہ بیچ میں کوئی پردہ حائل نہ ہو (۴) اونٹ کا گوشت کھانا"}],[439,"محمود بن طحلا کہتے ہیں: میں نے ابوسلمہ سے کہا: بیشک آپ کا سوتیلا باپ سلیم آگ پر پکی چیزیں کھا کر وضو نہیں کرتا۔ انھوں نے سلیم کے سینے پر ہاتھ مارا اور کہا: میں زوجہ رسول سیدہ ام سلمہ رضی اللہ عنہا پر گواہی دیتا ہوں اور وہ رسول اللہ صلی اللہ علیہ وسلم پر گواہی دیتی ہیں کہ آپ صلی اللہ علیہ وسلم آگ پر پکی ہوئی چیز کھا کر وضو کرتے تھے۔","",{"t":"کیا آگ پر پکی ہوئی چیز ناقض وضو ہے؟","k":"أخرجه أحمد: ۶/ ۳۲۱\n(الصحيحة: ۲۱۲۱)"}],[440,"سیدنا معاویہ رضی اللہ عنہ کے غلام قاسم بیان کرتے ہیں: میں مسجد دمشق میں داخل ہوا، میں نے دیکھا کہ کچھ لوگ اکٹھے ہیں اور ایک بزرگ ان کو احادیث بیان کر رہا تھا، میں نے کہا: یہ بزرگ کون ہے؟ انھوں نے کہا کہ یہ سہیل بن حنظلہ ہے، پھر میں نے ان کو یہ کہتے ہوئے سنا، کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو گوشت کھائے، وہ وضو کرے۔“","",{"t":"کیا آگ پر پکی ہوئی چیز ناقض وضو ہے؟","k":"أخرجه أحمد: ۴/ ۱۸۰، ۵/ ۲۸۹\n(الصحيحة: ۲۳۲۲)","e":"ابتدائے اسلام میں آگ پر پکی ہوئی چیز کھانے کی وجہ سے وضو کرنا پڑتا تھا، لیکن آپ صلی اللہ علیہ وسلم نے بعد میں وضو کرنا ترک کر دیا اور بیسیوں مواقع ایسے ہیں کہ آپ صلی اللہ علیہ وسلم نے آگ پر پکی ہوئی چیز کھائی اور وضو کیے بغیر نماز پڑھی۔ اس موضوع پر سیدنا جابر رضی اللہ عنہ کی حدیث فیصلہ کن ہے، وہ کہتے ہیں: كَانَ آخِرُ الْأَمْرَيْنِ مِنْ رَسُولِ اللهِ تَرْكُ الْوُضُوءِ مِمَّا مَسَّتِ النَّارُ- ...... ”ان دو امور میں سے آگ پر پکی ہوئی چیز کھا کر وضو نہ کرنا رسول اللہ صلی اللہ علیہ وسلم کا آخری عمل تھا۔“ (ابوداود، نسائی) لیکن اونٹ کا گوشت کھانے سے وضو کرنا چاہیے، جیسا کہ سیدنا براء بن عازب رضی اللہ عنہ سے مروی ہے کہ آپ صلی اللہ علیہ وسلم سے اونٹ کا گوشت کھانے کی وجہ سے وضو کرنے کے بارے میں سوال کیا گیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: «تَوَضَّأُوا مِنْهَا-» ..... ”اس سے وضو کیا کرو۔“ پھر آپ سے بکری کا گوشت کھانے کی وجہ سے وضو کرنے کے بارے میں سوال کیا گیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس سے وضو نہ کرو۔“ (ابوداود: ۱۸۴، ترمذی: ۸۱، ابن ماجہ: ۴۹۴) اس سے معلوم ہوا کہ اونٹ کا گوشت کھانے کے بعد وضو کرنا چاہیے۔"}],[441,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ جب آپ صلی اللہ علیہ وسلم (اور آپ کی بیوی) کے ختنوں کے مقام مل جاتے تو آپ غسل کرتے۔","",{"t":"غسل کے واجب ہونے کی صورتیں","k":"أخرجه أحمد: ۶/ ۱۲۳، ۲۲۷، والطحاوي في ”شرح المعاني“: ۱/ ۳۳\n(الصحيحة: ۲۰۶۳)"}],[442,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب (عورت اور مرد) کی شرمگاہوں کے ختنے والے مقامات مل جائیں تو غسل واجب ہو جاتا ہے۔“ ان الفاظ کے ساتھ یہ حدیث سیدہ عائشہ، سیدنا عبد اللہ بن عمرو بن عاص اور سیدنا ابوہریرہ رضی اللہ عنہم وغیرہ سے مروی ہے۔","",{"t":"غسل کے واجب ہونے کی صورتیں","k":"۱- أما حديث عائشة: فأخرجه أحمد: ۶/ ۲۳۹، والترمذي: ۱/ ۲۳، وأحمد: ۲/ ۱۷۸، وأخرجه مسلم: ۱/ ۱۸۷ نحوه ۲- وأما حديث ابن عمرو: فأخرجه ابن ماجه: ۶۱۱، وأحمد: ۲/ ۱۷۸، والخطيب: ۱/ ۳۱۱، ۶/ ۲۸۳ ۳- وأما حديث أبي هريرة: فأخرجه البيهقي: ۱/ ۱۶۳، وأخرجه مسلم: ۱/ ۱۸۶ نحوه\n(الصحيحة: ۱۲۶۱)","e":"ابتدائے اسلام میں ایک رخصت تھی، سیدنا ابوسعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «الْمَاءُ مِنَ الْمَاءِ-» ...... ”(غسل کا) پانی، (مادہ منویہ کے) پانی سے ہے۔“ (مسلم: ۳۴۳) اس حدیث کا مفہوم یہ ہے کہ اس وقت غسل جنابت کیا جائے گا، جب مادہ منویہ خارج ہوگا، وہ احتلام کی صورت میں نکلے یا مباشرت کی صورت میں۔ لیکن بعد میں آپ صلی اللہ علیہ وسلم نے اس رخصت کو ختم کر دیا اور نیا حکم یہ صادر فرمایا کہ مرد کا حشفہ، عورت کی فرج میں داخل ہو جانے سے غسل فرض ہو جائے گا، انزال ہو یا نہ ہو۔ خلاصہ کلام یہ ہے کہ ابتدائے اسلام میں غسل جنابت کے فرض ہونے کی ”انزال“ والی ایک صورت تھی، بعد میں دو صورتیں ہو گئیں: (۱) انزال، وہ کسی صورت میں ہو جائے اور (۲) حشفہ کا عورت کی شرمگاہ میں داخل ہونا، مذکورہ بالا عنوان کی احادیث میں یہی دوسری صورت بیان کی گئی ہے۔ یاد رہے کہ ہمارے ہاں صرف مردوں کے ختنے کیے جاتے ہیں، جبکہ عرب لوگ عورتوں کے بھی ختنے کرتے تھے، جس کی ایک خاص صورت تھی۔"}],[443,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما سے روایت ہے، وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب دو آدمی قضائے حاجت کے لیے نکلیں تو ان میں سے ہر ایک دوسرے ساتھی سے چھپ جائے اور پاخانہ کرتے وقت آپس میں باتیں نہ کریں، کیونکہ ایسا کرنے پر اللہ تعالیٰ ناراض ہوتا ہے۔“","",{"t":"قضائے حاجت کے دوران ایک دوسرے سے پردہ کرنا اور باتیں کرنا","k":"کذا في ”الوهم والايهام“: ۲/ ۱۴۲/ ۲\n(الصحيحة: ۳۱۲۰)","e":"معلوم ہوا کہ قضائے حاجت کے دوران ستر کے پردے کا اہتمام کیا جائے، ویسے بھی آپ صلی اللہ علیہ وسلم کی تعلیمات کے مطابق میاں بیوی کے علاوہ ہر کسی سے شرمگاہ کو پردے میں رکھنے کا حکم دیا گیا ہے، بلکہ اکیلے آدمی کو چاہیے کہ اللہ تعالیٰ سے حیا کرتے ہوئے ننگا ہونے سے بچے۔"}],[444,"سیدنا سراقہ بن مالک بن جعشم رضی اللہ عنہ سے روایت ہے کہ جب وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس سے آتے تو اپنی قوم کو کچھ باتیں بیان کیں اور (امور دین) کی تعلیم دی۔ ایک دن ایک آدمی نے ان کے ساتھ مذاق کرتے ہوئے کہا: سراقہ کے لیے تو صرف یہی چیز رہ گئی ہے کہ وہ تمہیں قضائے حاجت کا طریقہ سکھائے۔ سراقہ نے (بات کو سنجیدگی میں تبدیل کرتے ہوئے) کہا: جب تم قضائے حاجت کے لیے جاؤ تو سایہ دار مقامات اور راستوں پر بیٹھنے سے بچو، چھوٹے چھوٹے پتھروں کا اہتمام کرو، اپنی (بائیں) پنڈلی پر زور دو اور طاق (پتھروں) سے استنجا کرو۔","",{"t":"قضائے حاجت کے آداب","k":"أخرجه الطبراني في ”المعجم الأوسط“: ۲/ ۱۶/ ۲ رقم ۵۳۳۱\n(الصحيحة: ۲۷۴۹)","e":"حکیم لوگ کہتے ہیں کہ بائیں پنڈلی پر زور دینے سے آدمی جلدی فارغ ہو جاتا ہے، کیونکہ مثانہ بائیں جانب ہے، اس طرح کرنے سے اس پر زور پڑتا ہے۔"}],[445,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما سے روایت ہے، وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب دو آدمی قضائے حاجت کے لیے نکلیں تو ان میں سے ہر ایک دوسرے ساتھی سے چھپ جائے اور پاخانہ کرتے وقت آپس میں باتیں نہ کریں، کیونکہ ایسا کرنے پر اللہ تعالیٰ ناراض ہوتے ہیں۔“","",{"t":"قضائے حاجت کے آداب","k":"کذا في ”الوهم والايهام“: ۲/ ۱۴۲/ ۲\n(الصحيحة: ۳۱۲۰)"}],[446,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم قضائے حاجت کا ارادہ فرماتے تو اس وقت تک کپڑا نہ اٹھاتے، جب تک زمین کے قریب نہ ہو جاتے۔","",{"t":"قضائے حاجت کے آداب","k":"أخرج أبو داود: ۱/ ۳-۴، وعنه البيهقي: ۱/ ۹۶\n(الصحيحة: ۱۰۷۱)","e":"معلوم ہوا کہ زمین کے قریب ہو کر ننگا ہونا چاہیے۔"}],[447,"سیدنا مغیرہ بن شعبہ رضی اللہ عنہ سے روایت ہے کہ جب آپ صلی اللہ علیہ وسلم قضائے حاجت کے لیے نکلتے تو دور چلے جاتے۔","",{"t":"قضائے حاجت کے آداب","k":"أخرجه أبو داود: ۱/ ۲، والنسائي: ۱/ ۹-۸، والترمذي: ۱/ ۳، والدارمي: ۱/ ۱۶۹، وابن ماجه: ۱/ ۱۳۹، والحاكم: ۱/ ۱۴۰\n(الصحيحة: ۱۱۵۹)","e":"آج کل شہروں میں تو باقاعدہ بیت الخلا کا نظام موجود ہے، جب انسان شہروں سے باہر یا دیہاتوں میں ہو تو آبادی سے دور جا کر قضائے حاجت کرے، تا کہ آبادی میں تعفن اور بدبو نہ پھیلے اور لوگوں کو گندگی سے تکلیف نہ پہنچے اور قضائے حاجت کرنے والے پر دوسروں کی نگاہ پڑنے کا اندیشہ کم ہو جائے۔ ”المذهب“ کے دو معانی مراد لیے جا سکتے ہیں: (۱) مصدر یعنی معنی ”ذَهاب“، جس کے معانی ہوں گے ”جانا“ اور (۲) ظرف کا صیغہ یعنی ”جانے کی جگہ“، اس سے مراد قضائے حاجت کی جگہ ہوگی۔ غور و فکر کیا جائے کہ کیا اس حدیث سے یہ استدلال کرنا ممکن ہے کہ حسبِ امکان دور والا بیت الخلا استعمال کیا جائے اور پھر اس کی مکمل صفائی کی جائے تا کہ کسی کو تکلیف نہ ہو۔"}],[448,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ آپ قضائے حاجت کے لیے مغمس مقام تک چلے جاتے تھے۔ نافع کہتے ہیں: مغمس، مکہ مکرمہ سے دو یا تین میلوں کے فاصلے پر واقع تھا۔","",{"t":"قضائے حاجت کے آداب","k":"رواه السراج في ”الثاني“ من ”الأول“ من ”مسنده“: ۲/ ۲، وابن السكن في ”سننه“\n(الصحيحة: ۱۰۷۲)"}],[449,"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں سے کوئی آدمی قضائے حاجت کے لیے بیٹھے تو وہ قبلہ کی طرف منہ نہ کرے نہ پیٹھ۔“","",{"t":"قضائے حاجت کے دوران کعبہ کی طرف منہ اور پیٹھ نہ کرنا اور اس کی پابندی کا ثواب","k":"أخرجه مسلم: ۱/ ۱۵۵\n(الصحيحة: ۱۳۰۱)"}],[450,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے قضائے حاجت کرتے وقت قبلہ کی طرف رخ نہ کیا نہ پیٹھ، اس کے لیے ایک نیکی لکھی جائے گی اور ایک برائی مٹا دی جائے گی۔“","",{"t":"قضائے حاجت کے دوران کعبہ کی طرف منہ اور پیٹھ نہ کرنا اور اس کی پابندی کا ثواب","k":"أخرجه الطبراني في ”الأوسط“: ۱/ ۳۲- مصورة الجامعة الأسلامية\n(الصحيحة: ۱۰۹۸)","e":"مزید احادیث میں بھی قضائے حاجت کے وقت قبلہ کی طرف منہ یا پیشت کرنے سے منع کیا گیا ہے، لیکن خود نبی کریم صلی اللہ علیہ وسلم سے قضائے حاجت کے وقت قبلہ کی طرف منہ کرنا اور پیٹھ کرنا دونوں ثابت ہیں، غور فرمائیں: سیدنا جابر رضی اللہ عنہ کہتے ہیں: نَهَى نَبِيُّ اللهِ صلى الله عليه وسلم أَنْ نَسْتَقْبِلَ الْقِبْلَةَ بِبَوْلٍ، فَرَأَيْتُهُ قَبْلَ أَنْ يُقْبَضَ بِعَامٍ يَسْتَقْبِلُهَا ...... ”نبی کریم صلی اللہ علیہ وسلم نے ہمیں پیشاب کرتے وقت قبلہ رخ ہونے سے منع کر رکھا تھا، لیکن میں نے آپ صلی اللہ علیہ وسلم کو وفات سے ایک سال قبل دیکھا کہ آپ صلی اللہ علیہ وسلم خود قبلہ رخ ہو کر قضائے حاجت کر رہے تھے۔“ (ابوداود: ۱۳، ترمذی: ۹، ابن ماجہ: ۳۲۵) سیدنا عبد اللہ بن عمر رضی اللہ عنہ کہتے ہیں: میں (اپنی بہن) ام المومنین سیدہ حفصہ رضی اللہ عنہا کے گھر کی چھت پر چڑھا اور نبی کریم صلی اللہ علیہ وسلم کو قضائے حاجت کرتے ہوئے دیکھا، اس وقت آپ کا منہ شام کی طرف اور پیٹھ کعبہ کی طرف تھی۔ (بخاری: ۱۴۵، مسلم: ۲۶۶) ان روایات کی وجہ سے سلف صالحین کے مختلف اقوال منظر عام پر آئے۔ مثال کے طور پر امت کے لیے کعبہ کی طرف منہ یا پیٹھ کرنا منع ہے، آپ صلی اللہ علیہ وسلم کا عمل آپ کے ساتھ خاص تھا۔ لیکن خصوصیت کا دعوی کرنے کے لیے دلیل کا ہونا ضروری ہے، بصورت دیگر آپ صلی اللہ علیہ وسلم کا ہر فعل امت کے لیے سنت اور حجت ہوگا۔ عمارتوں میں منہ یا پیٹھ کر لینے میں کوئی حرج نہیں، البتہ صحراؤں اور کھلے مقامات پر ایسا کرنے سے بچنا چاہیے، لیکن سیدنا جابر کی عام روایت سے اس کا ردّ ہوتا ہے۔ راجح بات یہ معلوم ہوتی ہے کہ نہی پر مشتمل آپ صلی اللہ علیہ وسلم کی قولی احادیث کا لحاظ کر کے قبلہ کی منہ یا پیٹھ کرنے سے بچنا چاہیے، لیکن اگر کوئی آپ صلی اللہ علیہ وسلم کے افعال کی اقتدا کرتے ہوئے قبلہ کی طرف منہ یا پیٹھ کر لیتا ہے، تو جائز ہوگا۔ اصل مصیبت یہ ہے کہ بعض مسائل میں ہمارا ذہن جامد ہو جاتا ہے اور ہم طبعی طور پر کچھ امور کے امکان کو ناممکن سمجھ بیٹھتے ہیں۔ اگر نبی کریم صلی اللہ علیہ وسلم قضائے حاجت کے وقت قبلہ کی طرف منہ یا پیٹھ کرنے سے منع کریں تو ہم فوراً قبول کر لیتے ہیں، لیکن اگر آپ صلی اللہ علیہ وسلم خود ایسی حالت میں قبلہ کی منہ یا پیٹھ کر کے جواز پیش کریں تو ہمیں اچھنبا ہوتا اور تردّد سا ہونے لگتا ہے، بھلا ایسے کیوں ہے؟ یہ تو کوئی قانون نہیں کہ جس ادب کو ہم اہم سمجھیں، اس کی موافقت کرنے والی احادیث کو فوراً تسلیم کر لیا جائے اور جو احادیث ہماری فطرت سے مطابقت نہ رکھتی ہوں، ان کے معاملے ”چونکہ چنانچہ“ شروع کر دیں۔ تحقیق کا اصول یہ ہے کہ تحقیقی مرحلہ شروع کرنے سے پہلے آدمی کسی ایک طرف ذہنی میلان نہ رکھتا ہو، وگرنہ اس کی کوشش جانبدارانہ ہوگی اور نتائج مشکوک ہو جائیں گے۔"}],[451,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں سے کوئی آدمی قضائے حاجت کرے تو تین دفعہ (اور ایک روایت کے مطابق) تین پتھروں سے استنجا کرے۔“ یہ حدیث سیدنا جابر، سیدنا سائب بن خلاد اور سیدنا ابو ایوب الانصاری رضی اللہ عنہم سے مروی ہے۔","",{"t":"پتھروں سے استنجا کرنے کے احکام","k":"۱- أما حديث جابر؛ فأخرجه أحمد: ۳/ ۳۳۶، ۴۰۰، وابن خزيمة: ۱/ ۴۲/ ۷۱، ومن طريقه: البيهقي: ۱/ ۱۰۳، وابن أبي شيبة في ”المصنف“: ۱/ ۱۵۵ (۲)- وأما حديث السائب؛ فأخرجه البخاري في ”التاريخ“: ۲/ ۲/ ۱۵۱، والطبراني في ”المعجم الكبير“: ۷/ ۱۶۷/ ۶۶۲۳، وفي ”المعجم الأوسط“: ۲/ ۴۱۶-۴۱۷/ ۱۷۱۷- ط (۳) وأما حديث أبي ايوب؛ فأخرجه الطبراني في ”الكبير“: ۴/ ۲۰۸/ ۴۰۵۵، و”الاوسط“: ۴/ ۱۱۲/ ۳۱۷۰\n(الصحيحة: ۳۳۱۶)"}],[452,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”جو پتھروں سے استنجا کرے، وہ تین دفعہ پتھر استعمال کرے۔“","",{"t":"پتھروں سے استنجا کرنے کے احکام","k":"أخرجه الطبراني في ”الكبير“\n(الصحيحة: ۲۳۱۲)"}],[453,"سیدنا سلمہ بن قیس اشجعی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تو وضو کرے تو ناک جھاڑا کر اور جب پتھروں سے استنجا کرے، تو طاق (پتھر) استعمال کر۔“","",{"t":"پتھروں سے استنجا کرنے کے احکام","k":"أخرجه الترمذي: ۱/ ۸، والنسائي: ۱/ ۱۷ و ۷۷، وابن ماجه: ۴۰۶، وابن حبان: ۱۴۹، وأحمد: ۴/ ۳۳۹ و ۳۴۰، والخطيب: ۱/ ۲۸۶\n(الصحيحة: ۱۳۰۵)"}],[454,"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”جب کوئی آدمی پتھروں سے استنجا کرے تو وہ طاق پتھر استعمال کرے اور جب وہ ناک جھاڑے تو بھی (تعداد میں) طاق جھاڑے۔“","",{"t":"پتھروں سے استنجا کرنے کے احکام","k":"أخرجه الحميدي في ”مسنده“: ۹۵۷، وأخرجه الشيخان دون الفقرة الثانية\n(الصحيحة: ۱۲۹۵)","e":"پانی سے استنجا کرنا افضل ہے، اسی خصلت کی بنا پر اللہ تعالیٰ نے اہل قبا کی طہارت کی تعریف کی تھی، لیکن پتھروں سے استنجا کرنا بھی درست ہے، جو آپ صلی اللہ علیہ وسلم سے قولاً و فعلاً ثابت ہے اور پانی کی قلت کی وجہ سے اکثر صحابہ کرام کا یہی معمول تھا۔ ہاں یہ ضروری ہے کہ وہ کم از کم تین پتھر ہوں، جیسا کہ مفصل روایات گزر چکی ہیں، نیز سیدنا سلمان رضی اللہ عنہ بیان کرتے ہیں: أَجَلْ، نَهَانَا أَنْ نَسْتَقْبِلَ الْقِبْلَةَ بِغَائِطٍ أَوْ بَوْلٍ أَوْ أَنْ نَسْتَنْجِيَ بِالْيَمِينِ أَوْ أَنْ يَسْتَنْجِيَ أَحَدُنَا بِأَقَلَّ مِنْ ثَلَاثَةِ أَحْجَارٍ ...... ”جی ہاں! آپ صلی اللہ علیہ وسلم نے ہمیں منع فرمایا کہ ہم پیشاب یا پاخانہ کرتے وقت قبلہ کی طرف منہ نہ کریں یا دائیں ہاتھ سے استنجا کریں یا ہم میں سے کوئی تین سے کم پتھروں سے استنجا کرے۔“ (مسلم: ۵۴) اس لیے پتھروں سے استنجا کرنے کی صورت میں کم از کم تین پتھر استعمال کرنے چاہئیں۔ بہر حال آج کل اللہ تعالیٰ کی نعمتیں وافر مقدار میں موجود ہیں، ان میں سے ایک نعمت پانی اور قضائے حاجت کے لیے بنے ہوئے صاف ستھرے واش رومز ہیں، اس لیے پانی سے استنجا کرنے کا اہتمام کرنا چاہیے۔"}],[455,"سیدنا جابر بن عبد اللہ رضی اللہ عنہما سے روایت ہے کہ ایک آدمی نبی کریم صلی اللہ علیہ وسلم کے پاس سے گزرا، اس حال میں کہ آپ پیشاب کر رہے تھے، اس نے آپ کو سلام کہا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جب مجھے اس حالت میں پاؤ تو مجھے سلام نہ کہا کرو، اگر آئندہ تم نے ایسے کیا تو میں تمہارے سلام کا جواب نہیں دوں گا۔“","",{"t":"قضائے حاجت کرنے والے کو سلام نہ کہا جائے","k":"رواه ابن ماجه: ۱/ ۱۴۵-۱۴۶، وابن أبي حاتم في ”العلل“: ۱/ ۳۴\n(الصحيحة: ۱۹۷)","e":"معلوم ہوا کہ قضائے حاجت کرنے والے شخص کو سلام نہ کہا جائے، وگرنہ سلام کہنے والا جواب کا مستحق نہیں ہوگا۔"}],[456,"سیدنا زید بن ارقم رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بیشک طہارت خانوں میں (شیطان) حاضر ہوتے ہیں، اس لیے جو آدمی بیت الخلا میں آئے تو یہ دعا پڑھے: میں خبیث جنوں اور خبیث جنیوں سے اللہ تعالیٰ کی پناہ میں آتا ہوں۔“","",{"t":"بیت الخلا میں داخل ہونے کی دعا اور اس کی وجہ","k":"أخرجه أبو داود: ۱/ ۳، وابن ماجه: ۱/ ۱۲۷، وابن حبان: ۱۲۶، والبيهقي: ۱/ ۹۶، والطيالسي: رقم ۶۷۹، وأحمد: ۴/ ۳۶۹-۳۷۳\n(الصحيحة: ۱۰۷۰)","e":"اس حدیث میں قضائے حاجت کے لیے بیت الخلا میں داخل ہوتے وقت دعا پڑھنے کی وجہ بیان کی گئی ہے۔ اس موقع پر صرف بسم اللہ پڑھنا بھی کافی ہے، جیسا کہ سیدنا علی رضی اللہ عنہ سے مروی ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: «سِتْرُ مَا بَيْنَ الْجِنِّ وَعَوْرَاتِ بَنِي آدَمَ إِذَا دَخَلَ الْكَنِيفَ أَنْ يَقُولَ: بِسْمِ اللهِ-» ...... ”جنوں اور اولاد آدم کے ستروں کے مابین پردہ حاصل کرنے کے لیے بندے کو چاہیے کہ بیت الخلا میں داخل ہوتے وقت بسم اللہ پڑھے۔“ (ابن ماجہ: ۲۹۷) قضائے حاجت سے فارغ ہونے کے بعد «غُفْرَانَكَ» پڑھنا چاہیے۔ (ابوداود: ۳۰، ترمذی: ۷، ابن ماجہ: ۳۰، نسائی: ۳۳) جس حدیث میں درج ذیل دعا کا ذکر ہے، وہ ضعیف ہے «الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنِّي الْأَذَى وَعَافَانِي-» (ابن ماجہ: ۳۰۱)"}],[457,"سیدنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب کوئی آدمی اچھی طرح وضو کرتا ہے، پھر مسجد کی طرف نکلتا ہے اور اس کو نکالنے والی چیز صرف نماز ہوتی ہے، تو (جب تک وہ چلتا رہتا ہے) اس کے بائیں پاؤں کی وجہ سے برائی مٹی رہتی ہے اور دوسرے پاؤں کی وجہ سے نیکی لکھی جاتی رہتی ہے، حتی کہ وہ مسجد میں داخل ہو جاتا ہے۔“","",{"t":"مسجد کی طرف باوضو چل کر جانے کا ثواب","k":"أخرجه الطبراني في ”المعجم الكبير“: ۳/ ۱۹۸/ ۱، والحاكم: ۱/ ۲۱۷، والبيهقي في ”الشعب“\n(الصحيحة: ۱۲۹۶)","e":"اگر چہ آج کل مساجد میں وضو گاہوں کا انتظام موجود ہے، بہر حال گھر سے باوضو ہو کر آنا باعث اجر اور افضل عمل ہے، دوسرا یہ سبق ملا کہ جب آدمی نماز ادا کرنے کے لیے مسجد کی طرف جا رہا ہو تو اس کے ذہن میں نماز کے علاوہ کوئی اور مقصد نہیں ہونا چاہیے۔"}],[458,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب کوئی آدمی نماز کے لیے وضو کر لیتا ہے، تو پھر وہ اپنی انگلیوں میں تشبیک نہ دے۔“","",{"t":"نماز کے لیے وضو کرنے کے بعد تشبیک منع ہے","k":"أخرجه الطبراني في ”الأوسط“: ۱/ ق ۴-۵\n(الصحيحة: ۱۲۹۴)","e":"تشبیک: ایک ہاتھ کی انگلیوں کو دوسرے ہاتھ کی انگلیوں میں مضبوطی کے ساتھ داخل کرنا۔ سیدنا ابوسعید خدری رضی اللہ عنہ سے مروی ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: «إِذَا كَانَ أَحَدُكُمْ فِي الْمَسْجِدِ فَلَا يُشَبِّكَنَّ، فَإِنَّ التَّشْبِيكَ مِنَ الشَّيْطَانِ-» ...... ”جب کوئی آدمی مسجد میں ہو تو وہ (اپنے ہاتھوں کی انگلیوں میں) تشبیک نہ دے، کیونکہ تشبیک شیطان کی طرف سے ہے۔“ (مسند احمد: ۳/ ۴۳) لیکن ذہن نشین رکھیں کہ تشبیک مطلق طور پر منع نہیں ہے، بلکہ صرف اس وقت منع ہے، جب آدمی نماز کے قصد سے مسجد کی طرف جا رہا ہو، یا نماز کا انتظار کر رہا ہو یا نماز ادا کر رہا ہو، کیونکہ ایک حدیث میں تشبیک سے منع کرنے کی وجہ یہ بیان کی گئی ہے کہ جب آدمی نماز کے لیے مسجد کی طرف جا رہا ہو تو وہ نماز میں ہی ہوتا ہے۔ ان صورتوں کے علاوہ کئی مقامات پر آپ صلی اللہ علیہ وسلم سے تشبیک کرنا ثابت ہے، جیسا کہ سیدنا ابو ہریرہ اور سیدنا ذو الیدین رضی اللہ عنہما والی حدیث میں ہے کہ آپ صلی اللہ علیہ وسلم نے دو رکعتوں کے بعد سلام پھیر دیا اور مسجد میں پڑھی ہوئی ایک لکڑی کے ساتھ ٹیک لگا کر کھڑے ہو گئے، جب کہ آپ صلی اللہ علیہ وسلم نے تشبیک کی ہوئی تھی۔ (بخاری، مسلم) اسی طرح سیدنا ابو موسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ایک مومن دوسرے مومن کے لیے ایک عمارت کی طرح ہے، کہ اس کا بعض اس کے بعض کو مضبوط کرتا ہے۔“ پھر آپ صلی اللہ علیہ وسلم نے بات سمجھانے کے لیے تشبیک کی۔ (بخاری)"}],[459,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے (سیدہ ام عطیہ سے) فرمایا: ”جب تو (کسی لڑکی کا) ختنہ کرے تو کچھ کھال چھوڑ دیا کر اور (کاٹنے میں) مبالغہ آمیزی نہ کیا کر، کیونکہ یہ چیز چہرے کو خوبصورت بنانے والی اور اسے خاوند کے لیے مقبول بنانے والی ہے۔“","",{"t":"عورت کا ختنہ","k":"رواه الدولابي: ۲/ ۱۲۲، والخطيب في ”تاريخ“: ۵/ ۳۲۷، والطبراني في ”الأوسط“: ۳/ ۱۳۳/ ۲۲۷۴\n(الصحيحة: ۷۲۲)","e":"عرب میں بچی کا بھی ختنہ کیا جاتا تھا، اب بھی عرب کے بعض علاقوں میں یہ ختنہ کیا جاتا ہے۔ اس حدیث میں ختنہ کرنے والی عورت کے لیے ختنے کا طریقہ اور وجہ بیان کی گئی ہے۔"}],[460,"سیدہ خولہ بنت حکیم رضی اللہ عنہا سے روایت ہے کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے اُس عورت کے بارے میں دریافت کیا، جو مرد کے (خواب) کی طرح خواب دیکھتی ہے کہ (اسے احتلام ہو گیا ہے)؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس پر غسل کا کوئی حکم نہیں لگایا جا سکتا، جب تک انزال نہ ہو، جیسا کہ مرد پر غسل فرض نہیں ہوتا، جب تک انزال نہ ہو۔“","",{"t":"مردو زن دونوں کو احتلام ہوسکتا ہے جب تک انزال نہ ہو، صرف خواب سے غسل واجب نہیں ہوتا","k":"أخرجه ابن ماجه: ۶۰۲، وأخرجه النسائي: ۱/ ۴۲ بلفظ: ((إِذَا رَأَتِ الْمَاءَ فَلْتَغْتَسِلْ))\n(الصحيحة: ۲۱۸۷)"}],[461,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ سیدہ ام سلیم رضی اللہ عنہا نے رسول اللہ صلی اللہ علیہ وسلم سے اُس عورت کے بارے میں سوال کیا جو مرد کے (خواب) کی طرح خواب دیکھتی ہے (کہ اسے احتلام ہوا ہے)؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب وہ (نشانانت سے اندازہ لگا لے) کہ اسے انزال ہوا ہے تو اس پر غسل (جنابت) کرنا فرض ہے۔“ سیدہ ام سلمہ رضی اللہ عنہا نے کہا: کیا اس طرح بھی ہوتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جی ہاں، مرد (کی منی) کا پانی گاڑھا اور سفید ہوتا ہے، جبکہ عورت (کی منی) کا پانی زرد اور پتلا ہوتا ہے، (جماع کے وقت) جس کا (مادہ منویہ) سبقت لے جائے اور غالب آ جائے، بچے کی مشابہت اس سے ہو جاتی ہے۔“","",{"t":"مردو زن دونوں کو احتلام ہوسکتا ہے جب تک انزال نہ ہو، صرف خواب سے غسل واجب نہیں ہوتا","k":"أخرجه مسلم: ۱/ ۱۸۲، وأبو عوانة: ۱/ ۲۸۹، وابن ماجه: ۶۰۱، وأحمد: ۳/ ۱۲۱-۱۹۹، ۲۸۲\n(الصحيحة: ۱۳۴۲)","e":"احتلام کے ہونے یا نہ ہونے کے بارے میں ضابطہ یہ ہے کہ بیدار ہونے کے بعد کپڑے اور جسم کو دیکھا جائے کہ ان پر مادہ منویہ کے نشانات موجود ہیں یا نہیں، اگر ہیں تو غسل جنابت کیا جائے، بصورت دیگر غسل واجب نہیں ہوگا۔ یہ ضابطہ پیش کرنے کی وجہ یہ ہے کہ بسا اوقات انسان گندا خواب دیکھتا ہے اور اسے خواب میں انزال بھی ہوتا ہے، لیکن کپڑے اور جسم پر داغ نظر نہیں آتا، اس کا مطلب یہ ہوگا کہ اسے محض ایک خواب آیا تھا، اسی طرح بسا اوقات خواب نہیں آتا، لیکن نیند میں انزال ہو جاتا ہے اور کپڑے پر نشانات بھی نظر آ رہے ہوتے ہیں، ایسی صورت میں غسل فرض ہو جاتا ہے۔ عورتوں کو چاہیے کہ وہ غافل نہ ہوں اور اپنے متعلقہ مسائل دریافت کیا کریں، اگر طبعی شرم و حیا آڑے آ جائے تو آج کل فون یا خط وغیرہ کے ذریعے معلومات حاصل کی جا سکتی ہیں۔"}],[462,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”جب تم میں کوئی آدمی نماز کی حالت میں بے وضو ہو جائے، تو وہ ناک پکڑ کر نکل جائے۔“","",{"t":"دوران نماز بے وضو ہو جانے والا کیسے نکلے؟","k":"أخرجه ابن ماجه: ۱۲۲۲\n(الصحيحة: ۲۹۷۶)","e":"ناک پکڑ کر صف سے نکلنے کا فائدہ یہ ہوگا کہ دوسرے نمازیوں کو معلوم ہو جائے گا کہ یہ شخص بے وضو ہو گیا ہے۔ بصورت دیگر بدگمانی کی کوئی شکل پیدا ہو سکتی ہے۔"}],[463,"ابن جریج کہتے ہیں: مجھے عثیم بن کلیب جہنی کے حوالے یہ خبر دی گئی ہے کہ انھوں نے اپنے باپ اور انھوں نے اپنے دادا سے بیان کیا ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئے اور کہا: میں مسلمان ہو گیا ہوں۔ آپ صلی اللہ علیہ وسلم نے اسے فرمایا: ”کفر کے بال اتار پھینک۔“ یعنی منڈوا دے۔ وہ کہتے ہیں: پھر ایک دوسرے راوی نے ان سے یہ روایت بیان کی کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”کفر کے بالوں کو اتار پھینک اور ختنہ کر۔“","",{"t":"قبولیت اسلام کے وقت سر کے بال منڈوانا اور ختنہ کروانا","k":"أخرجه عبد الرزاق في ”المصنف“: ۲/ ۱۰/ ۹۸۳۵، ومن طريقه أحمد: ۳/ ۴۱۵، وأبو داود: ۳۵۶، ومن طريقه البيهقي: ۱/ ۱۷۲، والطبراني في ”المعجم الكبير“: ۲۲/ ۳۹۵\n(الصحيحة: ۲۹۷۷)","e":"شارح ابو داود علامہ عظیم آبادی کہتے ہیں: اللہ تعالیٰ بہتر جاننے ہیں، بہر حال ایسے معلوم ہوتا ہے کہ اس حدیث کا معنی و مفہوم یہ ہے کہ مسلمان ہونے والا ہر شخص اپنے سر کے بال منڈوا دے۔ یہاں ”شعر الکفر“ کہہ کر بالوں کی کفر کی طرف اضافت کی گئی ہے، اس سے معلوم ہوتا ہے کہ یہ بالوں کا کوئی خاص ڈیزائن تھا، جسے کافروں کی علامت سمجھا جاتا تھا، یہ علامتیں مختلف علاقوں میں مختلف ہوتی ہیں، ............ نیز اس حدیث سے معلوم ہوا کہ ختنہ اسلام کی علامت ہے اور اسلام قبول کرنے والے پر ختنہ کروانا واجب ہے۔ (عون المعبود: ۱/ ۲۰۸) امام البانی رحمہ اللہ نے اس حدیث کے شواہد ذکر کیے ہیں، جن سے معلوم ہوتا ہے کہ ختنہ کروانا ضروری ہے، اگرچہ مسلمان ہونے والا بڑی عمر کا آدمی ہو، جیسا کہ حضرت ابراہیم علیہ السلام نے اسی (۸۰) سال کی عمر کے بعد ختنہ کیا تھا۔ (ملاحظہ ہو: صحیحہ: ۲۹۷۷)"}],[464,"سیدہ عائشہ رضی اللہ عنہا کہتی ہیں: بے شک سیدہ فاطمہ بنت حبیش رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں اور کہا: مجھے استحاضے (کا خون) آتا ہے، پس میں پاک نہیں ہوتی تو کیا میں نماز چھوڑ دوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”یہ تو کوئی رگ (پھٹ گئی) ہے، یہ حیض کا خون نہیں ہے، جب حیض کا خون آنے لگے تو اس وقت نماز چھوڑ دیا کرو اور جب وہ ختم ہو جائے تو خون کو دھو دیا کرو اور ہر نماز کے لیے وضو کیا کرو اور نماز پڑھا کر، حتی کہ پھر (حیض) کا وقت آ جائے۔“","",{"t":"استحاضہ اور اس کے احکام","k":"أخرجه الشيخان وأبو عوانة في ”صحاحهم“، وأصحاب ”السنن“ الأربعة، ومالك، والدارمي، والدارقطني، والبيهقي، وأحمد\n(الصحيحة: ۳۰۱)","e":"عورت کی فرج سے بہنے والے خون کی تین اقسام ہیں: (۱) حیض (ماہواری کا خون): عورت کے رحم سے بہنے والا خون، جو ولادت یا امراض سے سلامتی کی حالت میں بلوغت کے بعد مخصوص ایام میں خارج ہوتا ہے، شریعت میں اس کی کم از کم یا زیادہ سے زیادہ مقدار کا کوئی تعین نہیں کیا گیا۔ (۲) نفاس: وہ خون جو بچے کی ولادت کے بعد آتا ہے، اس کی کم از کم مدت کا کوئی تعین نہیں، البتہ زیادہ سے زیادہ مدت چالیس دن ہے، اگر چالیس دن کے بعد خون جاری رہے تو اسے استحاضہ کا خون سمجھا جائے گا۔ حیض اور نفاس کے احکام ایک ہیں، دونوں میں نماز پڑھنا معاف ہے، لیکن روزوں کی قضائی دینا ضروری ہے۔ (۳) استحاضہ: وہ خون ہے، جو کسی رگ کے پھٹنے کی وجہ سے عورت کی شرمگاہ سے خارج ہوتا ہے۔ ایسی عورت کو مستحاضہ کہتے ہیں۔ اس حدیث میں اسی خون کا ذکر ہے، ایسی عورت نماز روزہ سے مستثنی نہیں ہے، البتہ نماز کے لیے طہارت کا طریقہ تھوڑا سا مختلف ہے۔ مستحاضہ نماز ادا کرنے کے لیے طہارت کے درج ذیل طریقوں میں کوئی ایک طریقہ اختیار کر لے: (۱) ہر نماز کے لیے علیحدہ وضو کرے، ہر نماز کے لیے طہارت حاصل کرنے کی یہ کم از کم صورت ہے۔ (۲) ابوداود، ترمذی اور ابن ماجہ کی روایت سے معلوم ہوتا ہے کہ ہر دو نمازوں کے لیے غسل کرے اور پہلی نماز ادا کرنے کے بعد پھر وضو کرے، یہ طریقہ آپ صلی اللہ علیہ وسلم کو زیادہ پسند تھا۔ اس کی صورت یہ ہوگی کہ ظہر کو آخری وقت میں اور عصر کو پہلے وقت میں ادا کرنے کے لیے دونوں کے لیے غسل کرے، پھر نماز ظہر ادا کر کے عصر کے لیے صرف وضو کرے۔ مثال کے طور پر اگر نماز ظہر کا وقت (۳:۳۰) بجے ختم ہو جاتا ہے، تو ایسی عورت کو نماز ظہر پڑھنے کے لیے جتنے منٹ درکار ہیں، اتنا وقت پہلے غسل اور وضو مکمل کر کے نماز ظہر شروع کر دے، جب یہ ظہر سے فارغ ہوگی تو (۳:۳۰) بج چکے ہوں گے، اس وقت وہ فوراً وضو کر کے عصر کی نماز شروع کر دے گی۔ یہی معاملہ مغرب و عشا کا ہوگا، اسی طرح فجر کی نماز کے لیے غسل اور وضو کا اہتمام کیا جائے گا۔ (۳) ہر نماز کے لیے غسل کرے، جیسا کہ سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہے کہ جب سیدہ ام حبیبہ رضی اللہ عنہا نے استحاضہ کی شکایت کی تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”حیض کی مدت ٹھہر کر رہو، پھر غسل کرو۔“ پس وہ ہر نماز کے لیے غسل کرتی تھیں۔ (مسلم) اگر چہ اس میں صرف ام حبیبہ کا فعل نقل کیا گیا ہے، لیکن ابوداود کی روایت کے الفاظ یہ ہیں: فَأَمَرَ هَا بِالْغُسْلِ لِكُلِّ صَلَاةٍ۔ اور فَقَالَ لَهَا النَّبِيُّ صلى الله عليه وسلم: «اغْتَسِلِي لِكُلِّ صَلَاةٍ-» امام ابوداود رحمہ اللہ نے ان روایات کو محفوظ اور امام البانی رحمہ اللہ نے صحیح قرار دیا ہے، اور دوسری صورت میں پیش کیے گئے طریقے سے بھی ہر نماز کے لیے غسل کرنے کا استدلال کیا جا سکتا ہے۔"}],[465,"سیدنا مہاجر بن قنفذ رضی اللہ عنہ سے روایت ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس اس حال میں آئے کہ آپ پیشاب کر رہے تھے، اس نے آپ صلی اللہ علیہ وسلم کو سلام کہا، لیکن آپ صلی اللہ علیہ وسلم نے جواب نہ دیا، پہلے وضو کیا (پھر جواب دیا اور) معذرت کرتے ہوئے فرمایا: ”میں بغیر وضو کے اللہ تعالیٰ کا ذکر کرنا ناپسند کرتا ہوں۔“","",{"t":"ذکر خدا کے لیے طہارت کا اہتمام کیا جائے","k":"أخرجه أبو داود: ۱/ ۴، والنسائي: ۱/ ۱۶، والدارمي: ۲/ ۲۸۷، وابن ماجه: ۱/ ۱۴۵، وابن خزيمة في ”صحيحه“: ۲۰۶، وعنه ابن حبان: ۱۸۹، والحاكم: ۱/ ۱۶۷، وعنه البيهقي: ۱/ ۹۰، وأحمد: ۵/ ۸۰\n(الصحيحة: ۸۳۴)","e":"بلاشک و شبہ آدمی وضو اور غسل کے بغیر اللہ تعالیٰ کا ذکر کر سکتا ہے، البتہ بہتر اور مستحب یہ ہے کہ طہارت کا مکمل اہتمام کرے۔ علامہ البانی رحمہ اللہ لکھتے ہیں: چونکہ ”السلام“ اللہ تعالیٰ کا نام ہے، جیسا کہ سیدنا عبد اللہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: «السَّلَامُ اسْمٌ مِنْ أَسْمَاءِ اللهِ وَضَعَهُ فِي الْأَرْضِ، فَأَفْشُوهُ بَيْنَكُمْ، فَإِنَّ الرَّجُلَ الْمُسْلِمَ إِذَا مَرَّ بِقَوْمٍ فَسَلَّمَ عَلَيْهِمْ فَرَدُّوا عَلَيْهِ، كَانَ لَهُ عَلَيْهِمْ فَضْلُ دَرَجَةٍ، فَإِنْ لَمْ يَرُدُّوا عَلَيْهِ رَدَّ عَلَيْهِ مَنْ هُوَ خَيْرٌ مِنْهُمْ وَأَطْيَبُ-» (صحیحہ: ۱۸۹۴) ...... ”سلام“ اللہ کا نام ہے، جسے اس نے زمین میں اتارا، پس تم آپس میں اسے عام کر دو، جب کوئی مسلمان آدمی کسی گروہ کے پاس سے گزرتا ہے اور ان پر سلام کرتا ہے اور وہ اس کے سلام کا جواب دیتے ہیں، تو سلام دینے والے کو ان پر فضیلت حاصل ہوتی ہے۔ اور اگر وہ جواب نہ دیں تو اسے ایسی (ہستیاں) جواب دیتی ہیں جو ان سے زیادہ بہتر اور پاکیزہ ہوتی ہیں۔“ اس لیے آپ صلی اللہ علیہ وسلم نے طہارت کا انتظار کیا، یہ حدیث اس بات پر دلالت کرتی ہے کہ بغیر وضو کے تلاوتِ قرآن تو بالاولی مکروہ ہوگی، اس لیے مطلق طور پر یہ نہیں کہا جا سکتا کہ بے وضو آدمی تلاوت کر سکتا ہے، جیسا کہ بعض اہل الحدیث بھائیوں کا خیال ہے۔ (صحیحہ: ۸۳۴) یعنی وضو کا اہتمام کرنے کی رغبت دلائی جائے۔"}],[466,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم بیت الخلا سے نکلتے تو وضو کرتے۔","",{"t":"آپ صلی اللہ علیہ وسلم بیت الخلا سے نکل کر وضو کرتے","k":"أخرجه أحمد: ۶/ ۱۸۹\n(الصحيحة: ۳۴۸۱)"}],[467,"ابراہیم سے مرسلاً روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم آرہے ہوتے تو عمدہ (اور پاکیزہ) خوشبو سے پہچان لیا جاتا تھا۔","",{"t":"آپ صلی اللہ علیہ وسلم خوشبو استعمال کرتے تھے","k":"أخرجه ابن سعد: ۱/ ۳۹۹، والدارمي: ۱/ ۳۲\n(الصحيحة: ۲۱۳۷)"}],[468,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کے لیے کالے رنگ کا اونی جبہ تیار کیا۔ آپ صلی اللہ علیہ وسلم نے اسے زیب تن کیا، لیکن جب پسینہ آیا تو اس سے اون کی بو آنے لگی، اس لیے آپ صلی اللہ علیہ وسلم نے اسے اتار دیا، کیونکہ پاکیزہ (اور عمدہ) خوشبو آپ صلی اللہ علیہ وسلم کو اچھی لگتی تھی۔","",{"t":"آپ صلی اللہ علیہ وسلم خوشبو استعمال کرتے تھے","k":"أخرجه أبو داود: ۲/ ۱۷۸، والحاكم: ۴/ ۱۸۸، ۱۸۹، وأحمد: ۶/ ۱۴۴، ۲۱۹، ۲۴۹، وابن سعد: ۱/ ۴۵۳\n(الصحيحة: ۲۱۳۶)","e":"خوشبو آپ صلی اللہ علیہ وسلم کی پسندیدہ چیز تھی۔"}],[469,"سیدنا عبد اللہ بن عباس رضی اللہ عنہما، سیدہ میمونہ رضی اللہ عنہا سے روایت کرتے ہیں، وہ کہتی ہیں: میں اور رسول اللہ صلی اللہ علیہ وسلم جنابت والے ہو گئے، میں نے ایک ٹب میں غسل کیا، کچھ پانی بچ گیا۔ جب رسول اللہ صلی اللہ علیہ وسلم تشریف لائے تو اس پانی سے غسل کیا۔ میں نے کہا: اس پانی سے تو میں نے بھی غسل کیا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”(جنبی فرد کے غسل کی وجہ سے) پانی پر جنابت کا حکم عائد نہیں ہوتا۔“","",{"t":"جنابت والے غسل سے بچے ہوئے پانی سے غسل کرنا","k":"رواه ابن سعد: ۸/ ۱۳۷، وأحمد: ۱/ ۳۳۷، ۶/ ۳۳۰\n(الصحيحة: ۲۱۸۵)","e":"ایک صحابی رسول بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عورت کو مرد کے بچے ہوئے پانی سے اور مرد کو عورت کے بچے ہوئے پانی سے غسل کرنے سے منع کیا۔ (ابوداود: ۸۱، نسائی: ۳۳۸) لیکن یہ نہی تنزیہی ہے، کیونکہ آپ صلی اللہ علیہ وسلم نے اپنی بیوی کے بچے ہوئے پانی سے غسل کیا ہے، خلاصہ کلام یہ ہے کہ افضل یہ ہے کہ بچے ہوئے پانی سے غسل نہ کیا جائے، لیکن آپ صلی اللہ علیہ وسلم نے غسل کر کے جواز پیش کر دیا ہے۔"}],[470,"سیدنا سلمان رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو وضو کرتا ہے اور مسجد کی طرف آتا ہے، وہ اللہ تعالیٰ کا مہمان ہوتا ہے اور میزبان پر یہ بات حق ہے کہ وہ میزبان کی تکریم کرے۔“","",{"t":"مسجد کی طرف آنے والا اللہ تعالیٰ کا مہمان ہے، اور ......","k":"أخرجه أبو الحسن بن الصلت في ”حديثه عن أبي بكر المطيري“: ق ۱/ ۷۶، والطبراني في ”الكبير“\n(الصحيحة: ۱۱۶۹)","e":"اگر مومن ان احادیث کو سامنے رکھے تو اسے مسجد کی طرف آنے میں اور مسجد میں نماز کی انتظار میں بیٹھنے میں لذت اور حلاوت محسوس ہوگی۔"}],[471,"سیدہ عائشہ رضی اللہ عنہا کہتی ہیں: اس آدمی کی تصدیق مت کرو، جو یہ بیان کرے کہ نبی کریم صلی اللہ علیہ وسلم کھڑے ہو کر پیشاب کرتے تھے، کیونکہ آپ صلی اللہ علیہ وسلم تو بیٹھ کر ہی پیشاب کرتے تھے۔","",{"t":"کیا بیٹھ کر پیشاب کرنا ضروری ہے؟","k":"أخرجه النسائي: ۱/ ۱۱، والترمذي: ۱/ ۱۷، وابن ماجه: ۱/ ۱۳۰، والطيالسي: ۱/ ۴۵- من ترتيبه، وأبو عوانة في ”صحيحه“: ۱/ ۱۹۸، والحاكم: ۱/ ۱۸۱، والبيهقي: ۱/ ۱۰۱، وأحمد: ۱/ ۱۳۶، ۱۹۲، ۲۱۳\n(الصحيحة: ۲۰۱)","e":"آپ صلی اللہ علیہ وسلم کا عام معمول یہی تھا کہ آپ بیٹھ کر پیشاب کرنے کا اہتمام کرتے تھے۔ لیکن کھڑے ہو کر پیشاب کرنا جائز ہے، جیسا کہ سیدنا حذیفہ رضی اللہ عنہ نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم گندگی کے ایک ڈھیر پر آئے اور کھڑے ہو کر پیشاب کیا۔ (بخاری: ۲۲۴، مسلم: ۲۷۳) سیدہ عائشہ رضی اللہ عنہا نے آپ صلی اللہ علیہ وسلم کے کھڑے ہو کر پیشاب کرنے کی نفی کی، اس چیز کو ان کے علم پر محمول کیا جائے گا، یعنی ان کو سیدنا حذیفہ رضی اللہ عنہ کی حدیث کا علم نہیں تھا۔ یہ بڑی عجیب بات ہے کہ اگر یہ حدیث بیان کی جائے کہ آپ صلی اللہ علیہ وسلم بیٹھ کر پیشاب کرتے تھے، تو ہم تسلیم کر لیتے ہیں، لیکن اگر یہ بیان کیا جائے کہ آپ صلی اللہ علیہ وسلم نے کھڑے ہو کر پیشاب کر کے جواز پیش کر دیا ہے تو ہم اچھنباہٹ اور حیرانگی کا اظہار کرتے ہیں۔ سوال یہ ہے کہ جواز اور عدم جواز کا معیار ہمارا ذہن ہے یا آپ صلی اللہ علیہ وسلم کا فیصلہ؟! مطلوب شریعت یہ ہے کہ پیشاب کے چھینٹوں سے بچا جائے، اگر کسی مقام پر بیٹھ کر پیشاب کرنا بچا جا رہا ہو تو ضروری ہے کہ کھڑے ہو کر پیشاب کیا جائے۔ رہا شرعی مسئلہ تو آپ صلی اللہ علیہ وسلم سے کوئی ایسی صحیح حدیث ثابت نہیں کہ جس میں کھڑے ہو کر پیشاب کرنے سے منع کیا گیا ہو۔ بلکہ صحابہ کرام میں سے سیدنا عمر، سیدنا علی، سیدنا زید بن ثابت، سیدنا عبد اللہ بن عمر، سیدنا سہل بن سعد، سیدنا انس بن مالک، سیدنا ابو ہریرہ اور سیدنا عروہ بن زبیر رضی اللہ عنہم سے کھڑے ہو کر پیشاب کرنا ثابت ہے۔ خلاصہ کلام یہ ہے کہ حتی الوسع بیٹھ کر پیشاب کرنے کا اہتمام کیا جائے، کیونکہ آپ صلی اللہ علیہ وسلم کا معمول یہی تھا، لیکن اگر کسی مقام پر کھڑے ہو کر پیشاب کرنا پڑ جائے تو اس میں کوئی مضائقہ نہ سمجھا جائے اور اگر کوئی جان بوجھ کر ایسے کرتا ہے تو اسے گناہ گار نہیں قرار دیا جا سکتا۔"}],[472,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک آدمی، نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور کہا: اے اللہ کے رسول! ہم سمندری سفر کرتے ہیں اور اپنے ساتھ تھوڑا بہت پانی لے جاتے ہیں۔ اگر ہم اس سے وضو کرنے لگ جائیں تو پیاسے رہ جاتے ہیں، پس کیا ہم (سمندر) کے پانی سے وضو کر سکتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”سمندر کا پانی پاک ہے اور اس کا مردار حلال ہے۔“","",{"t":"سمندر کا پانی طاہر و مطہر ہے","k":"أخرجه مالك: ۱/ ۴۴-۴۵، ومن طريق مالك اخرجه اصحاب السنن و غيرهم\n(الصحيحة: ۴۸۰)","e":"عام طور پر سمندر کا پانی کھارا اور نمکین ہونے کی وجہ سے، دوسرے پانیوں سے مختلف ہوتا ہے، اس لیے سائل کو شبہ ہو رہا تھا، آپ صلی اللہ علیہ وسلم نے اس کے شبہ کا ازالہ کر دیا اور اس کی ضرورت کے مطابق سمندر کے مردار کی حلّت کی بھی وضاحت کر دی۔"}],[473,"سیدہ ام سلمہ رضی اللہ عنہا سے روایت ہے، وہ کہتی ہیں: اے اللہ کے رسول! میں اپنے بالوں کو مضبوطی کے ساتھ گوندھتی ہوں، تو کیا جنابت کے غسل کے لیے ان کو کھول دیا کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”نہیں، تجھے سر پر تین چلو ڈالنا ہی کافی ہیں، اس کے بعد (بقیہ جسم) پر پانی بہا دیا کر، اس طرح تو پاک ہو جائے گی۔“","",{"t":"عورت غسل جنابت میں سر پر پانی کے تین چلو ڈالے","k":"رواه مسلم: ۱۷۸، وأصحاب ”السنن“ الأربعة، وأبو علي الحسين بن محمد اللحياني في ”حديثه“: ۱/ ۱۲۳، وابن أبي شيبة، والبيهقي: ۱/ ۱۸۱، وأحمد: ۶/ ۲۸۹ و ۳۱۴-۳۱۵\n(الصحيحة: ۱۸۹)","e":"اس حدیث میں عورت کے لیے ایک ایسی رخصت کا بیان ہے، جس میں اس کے لیے بہت آسانی پیدا کر دی گئی ہے۔ صحیح مسلم کی ایک روایت میں غسل جنابت اور غسل حیض دونوں کا ذکر ہے۔"}],[474,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان کو فرمایا، جبکہ وہ حائضہ تھیں: ”اپنے بالوں کو کھولو اور غسل کرو۔“","",{"t":"حائضہ عورت کا حج کے لیے غسل کرنا","k":"رواه ابن أبي شيبة في ”المصنف“: ۱/ ۲۶/ ۱، وابن ماجه: ۶۴۱\n(الصحيحة: ۱۸۸)","e":"اس حدیث کا ان روایات سے کوئی تضاد نہیں، جن میں غسل جنابت اور غسل حیض میں عورت کو سر پر صرف تین چلو ڈالنے کا حکم دیا گیا ہے، کیونکہ اس حدیث میں آپ صلی اللہ علیہ وسلم سیدہ عائشہ رضی اللہ عنہا کو صرف صفائی کے لیے غسل کرنے کا حکم دے رہے ہیں، جس میں بالوں کو کھولنا زیادہ مناسب ہے۔"}],[475,"سیدنا عبد اللہ بن عکیم رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مردار کے چمڑے اور پٹھے سے فائدہ حاصل نہ کرو۔“","",{"t":"مردار سے کوئی استفادہ نہ کیا جائے، لیکن ......","k":"أخرجه الطبراني في ”الأوسط“: ۲/ ۳۰۲/ ۱\n(الصحيحة: ۲۸۱۲)","e":"دوسری روایات میں وضاحت موجود ہے کہ مردار (حلال جانور) کے چمڑے کو رنگ کر پاک کیا جا سکتا ہے۔"}],[476,"حضرت عبد اللہ بن یزید سے روایت ہے، وہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”گھر کے اندر تھال میں پیشاب کو نہ پڑے رہنے دیا جائے، کیونکہ فرشتے اس گھر میں داخل نہیں ہوتے، جس میں پیشاب ہو۔ نیز کوئی بندہ غسل خانے میں پیشاب نہ کیا کرے۔“","",{"t":"گھر میں پیشاب پڑا نہ رہنے دیا جائے","k":"أخرجه الطبراني في ”الأوسط“: ص ۴-۳- مجمع البحرين نسخة الحرم المكي\n(الصحيحة: ۲۵۱۶)","e":"سیدنا رقیقہ رضی اللہ عنہا سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم کے پاس لکڑی کا ایک پیالہ تھا، جو آپ کی چارپائی کے نیچے ہوتا، آپ صلی اللہ علیہ وسلم رات کو اس میں پیشاب کرتے۔ (ابوداود: ۲۴، نسائی: ۱/ ۳۱) ان دو روایات میں جمع و تطبیق کی صورت یہ ہے کہ پہلی حدیث میں اس چیز سے منع کیا گیا ہے کہ گھر میں پیشاب پڑا رہے، کیونکہ کچھ وقت کے بعد اس سے بدبو آنے لگتی ہے، اور دوسری حدیث کو اس معنی پر محمول کریں گے کہ آپ صلی اللہ علیہ وسلم کے پیشاب والے برتن کو فوراً اٹھا کر باہر انڈیل دیا جاتا تھا کہ بدبو پیدا نہ ہو سکے۔ اس حدیث کا یہ تقاضا بھی ہے کہ گھروں میں بنے ہوئے بیت الخلا کی صفائی کا خاطر خواہ بندوبست کرنا چاہیے، وگرنہ پورے گھر میں بدبو پھیل جائے گی اور فرشتے داخل نہیں ہوں گے۔"}],[477,"سیدنا جریر رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس آیا ، اس حال میں کہ آپ صلی اللہ علیہ وسلم بیعت لے رہے تھے۔ میں نے کہا: اے اللہ کے رسول ! ہاتھ پھیلائیں ، تاکہ میں بھی آپ کی بیعت کروں اور آپ مجھ پر شرط لگائیں، کیونکہ آپ بہتر جانتے ہیں ۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”میں تجھ سے اس بات پر بیعت لیتا ہوں کہ تو اللہ تعالیٰ کی عبادت کرے گا، نماز قائم کرے گا، زکاۃ ادا کرے گا، مسلمانوں سے ہمدردی کرے گا اور مشرکوں سے علیحدگی اختیار کرے گا۔“","",{"t":"بیعتِ نبوی کے دوران اقامتِ صلاۃ کا تذکرہ","k":"أخرجه النسائي: ۲/۱۸۳ ، والبيهقي: ۹/۱۳ وأحمد: ۴/۳۶۵ ، والطبراني في ”المعجم الكبير“:۲/۳۵۹/ ۲۳۱۸\n(الصحيحة: ۶۳۶)","e":"نماز اسلام کا بنیادی اور انتہائی اہم رکن ہے، یہ خام خیالی ہے کہ نماز کے بغیر اسلام کی عمارت قائم رہ سکے۔ ارشادِ باری تعالیٰ ہے: ﴿وَأَقِيمُوا الصَّلاةَ وَلَا تَكُونُوا مِنَ الْمُشْرِكِينَ﴾ (سورۂ روم : ۳۱) ...... ”نماز قائم کرو اور مشرکوں میں سے نہ ہو جاؤ۔“ ارشادِ نبوی ہے: «بَيْنَ الرَّجُلِ وَبَيْنَ الشِّرْكِ وَالْكُفْرِ تَرْكُ الصَّلَاةِ» (صحيح مسلم) ...... ”(مسلمان) آدمی اور شرک و کفر کے درمیان (فرق) نماز کا چھوڑنا ہے۔“ یہی وجہ ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”سات سال کے بچے کو نماز پڑھنے کا حکم دینا شروع کر دو اور اگر وہ دس سال کا ہو جائے اور نماز میں سستی کرے تو اس (جرم) پر اسے سزا دو۔“ (ابو داود ) مذکورہ بالا حدیث میں جہاں نبی کریم صلی اللہ علیہ وسلم نے بیعت لیتے وقت اللہ تعالیٰ کی عبادت کی شرط لگائی، وہاں نماز کی ادائیگی کا حکم بھی دیا، یعنی بیعت برقرار رکھنے کے لیے جن امور کی ضرورت ہے، ان میں نماز کو بھی خاص مقام حاصل ہے۔ توحید و نماز کے ضمن میں زکوۃ ،مسلمانوں کے ساتھ ہمدردی و خیر خواہی اور مشرکوں سے علیحدگی اختیار کرنے کی شرائط لگانے سے ان تین امور کی اہمیت کا اندازہ ہوتا ہے۔ یاد رہے، مشرکین سے مفارقت کی سرحدیں نشت و برخاست سے دوری سے ہوتی ہوئیں تہذیب و تمدن، کلچر و آرٹ لائف اسٹائل اور شادی و مرگ کے امور تک پھیلی ہوئی ہیں ہندو پاک میں بالخصوص ہندوانہ مشرکانہ تہذیب سے جغرافیائی قرب کی بنا پر مقارفت کے اس آخری مفہوم سے تساہل برتا جاتا ہے۔"}],[478,"سیدنا عوف بن مالک رضی اللہ عنہ کہتے ہیں: ہم سات، آٹھ یا نو آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس موجود تھے۔ آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا: ”کیا تم رسول اللہ صلی اللہ علیہ وسلم کی بیعت نہیں کرتے ؟“ ہم نے کہا: ہم نے تھوڑا عرصہ پہلے ہی آپ کی بیعت کی تھی ۔ آپ صلی اللہ علیہ وسلم نے پھر فرمایا: ” کیا تم رسول اللہ صلی اللہ علیہ وسلم کی بیعت نہیں کرتے ؟“ ہم نے عرض کی: اے اللہ کے رسول! ہم تو آپ کی بیعت کر چکے ہیں۔ آپ صلی اللہ علیہ وسلم نے (تیسری دفعہ) فرمایا: ”کیا تم رسول اللہ صلی اللہ علیہ وسلم کی بیعت نہیں کرتے ؟“ سو ہم نے ( بیعت کے لیے ) اپنے ہاتھ پھیلا دیے اور کہا: اے اللہ کے رسول! ہم آپ صلی اللہ علیہ وسلم کی بیعت تو کر چکے ہیں، اس لیے ( آپ وضاحت کریں کہ اب کس چیز پر بیعت کریں؟“ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس بات پر کہ تم ایک اللہ کی عبادت کرو گے، اس کے ساتھ کسی کو شریک نہیں ٹھہراؤ گے، پانچ نمازیں پڑھو گے اور اللہ تعالیٰ کی اطاعت کرو گے۔“ اور ایک بات آہستہ انداز میں ارشاد فرمائی کہ ”لوگوں سے کسی چیز کا سوال نہیں کرو گے ۔“ میں نے دیکھا کہ اگر ان مذکورہ ( بیعت کنندگان ) میں سے بعض افراد کا کوڑا بھی زمین پر گر جاتا تو وہ کسی سے سوال نہیں کرتے تھے کہ وہ اسے اٹھا کر انھیں پکڑا دے (بلکہ وہ خود اٹھا لیتے تھے)۔","",{"t":"بیعتِ نبوی کے دوران اقامتِ صلاۃ کا تذکرہ","k":"رواه مسلم: ۳/۹۷ ، والنسائي: ۱/۲۲۹ واللفظ له ، وأبوداود: ۱۶۴۲ ، وابن ماجه: ۲۸۶۷ ، والطبراني في ”الكبير“: ۱۸/ رقم ۶۷ ، والمزي في ”تهذيب الكمال“: ۳۴/۲۹۲ ، وابن حبان: ۳۳۸۵، والطبراني في ”الكبير“ : ۱۸/ رقم ۶۸ ، وأحمد: ۶/۲۷\n(الصحيحة: ۳۶۰۰)","e":"سبحان اللہ ! صحابہ کرام رضی اللہ عنہم، نبی کریم صلی اللہ علیہ وسلم کی بیعت کر کے مشرف باسلام ہو چکے ہیں، لیکن انتہائی اہم امور کی نشاندہی اور تاکید کرنے کے لیے آپ صلی اللہ علیہ وسلم نے دوبارہ بیعت لینے کا اعلان کر دیا۔ پھر صحابہ کرام رضوان اللہ علیہم اجمعین کا جذبہ اطاعت رسول دیکھیں کہ آپ صلی اللہ علیہ وسلم کے حکم کی اسے اس حد تک قدردانی کی کہ اگر کوئی سواری پر سوار ہوتا اور اس کا کوڑا یا لاٹھی گر جاتی تو فرمودۂ رسول کے احترام میں سواری سے اتر کر اٹھا لیتا، لیکن کسی سے خدمت لینا گوارہ نہ کرنا۔ (لا تسألُوا)"}],[479,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کرتے ہوئے کہا: اے اللہ کے رسول! اللہ تعالیٰ نے اپنے بندوں پر کتنی نمازیں فرض کیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ نے اپنے بندوں پر پانچ نمازیں فرض کیں۔“ اس نے کہا: اے اللہ کے رسول ! آیا ان سے پہلے یا بعد میں بھی کوئی نماز (فرض) ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ نے اپنے بندوں پر پانچ نمازیں فرض کی ہیں۔“ آپ صلی اللہ علیہ وسلم نے یہ بات تین دفعہ دوہرائی۔ اس نے اللہ کی قسم اٹھاتے ہوئے کہا: میں ان ( پانچ نمازوں ) میں زیادتی کروں گا نہ کمی ۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ” اگر یہ (اپنے دعوے میں ) سچا ہے تو جنت میں ضرور داخل ہو گا ۔“","",{"t":"فرضی نمازوں کی تعداد","k":"أخرجه النسائي: ۱/۲۲۸-۲۲۹۔ القلم ، وابن حبان: ۲۵۱ ، والزيادة الثانية له ، وأحمد: ۳/۲۶۷\n(الصحيحة: ۲۷۹۴)","e":"حدیث مبارکہ سے معلوم ہوا کہ ایک دن میں پانچ نمازیں فرض ہیں، نیز یہ بھی پتہ چلا کہ جو آدمی پانچ نمازوں کی حفاظت کرے گا، اللہ تعالیٰ اسے جنت میں داخلہ نصیب فرمائے گا۔ نمازوں سے پہلے اور بعد والی سنتیں فرض نہیں ہیں، لیکن ان کی ادائیگی پر بے حد اجر و ثواب کی بشارتیں سنائی گئی ہیں، جیسا کہ سیدہ ام حبیبہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «مَا مِنْ عَبْدٍ مُسْلِمٍ يُصَلَّى لِلَّهِ كُلَّ يَوْمٍ ثِنْتَيْ عَشَرَةَ رَكْعَةً تَطَوُّعًا غَيْرَ فَرِيضَةٍ إِلَّا بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ -» (صحيح مسلم) ...... ”جو مسلمان ہر روز اللہ تعالیٰ کے لیے بارہ رکعت نفلی نماز پڑھتا ہے، اللہ تعالیٰ اس کے لیے جنت میں ایک گھر بنا دیں گے۔“ ترمذی کی روایت کے مطابق ان بارہ رکعات کی تفصیل یہ ہے: فجر سے پہلے دو، ظہر سے پہلے چار اور اس کے بعد دو، مغرب کے بعد دو اور عشا کے بعد دو۔ اسی نفلی نماز کو ہمارے معاشرے میں سنن مؤکدہ کہا جاتا ہے۔ علمائے حدیث نے اس حدیث سے یہ استدلال بھی کیا ہے کہ نماز وتر فرض نہیں ہے، بلکہ وہ نفلی نماز ہے اور ان شاء اللہ یہ استدلال درست ہے، اس پر مزید بحث نماز وتر کے عنوان میں کی جائے گی۔ (واللہ اعلم بالصواب)"}],[480,"سیدنا عبد اللہ رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت والے دن (حقوق اللہ میں سے) لوگوں کا سب سے پہلے نماز کا حساب ہو گا اور (حقوق العباد میں سے) سب سے پہلے خون کے بارے میں فیصلہ ہو گا ۔“","",{"t":"نماز ، دوسرے اعمال کے مقبول یا غیر مقبول ہونے کے لیے معیار ہے","k":"أخرجه النسائي: ۲/۱۶۳ ، وابن نصر في ”الصلاة“ ق ۱/۳۱ ، وابن أبي عاصم في ”الأوائل“: ق ۲/۴ ، والطبراني في ”المعجم الكبير“ : ۱۰۴۲۵ ، والقضاعي في ”مسند الشهاب“: ۱/۲/۱۱، والحديث شطره الاول له شواهد، وشطره الثاني في ”الصحيحين“ والنسائي\n(الصحيحة: ۱۷۴۸)"}],[481,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”قیامت کے روز سب سے پہلے بندے کا نماز کے بارے میں محاسبہ کیا جائے گا۔ اگر وہ درست ہوئی تو اس کے بقیہ اعمال بھی درست ہوں گے اور اگر اس میں خرابی آگئی تو بقیہ اعمال میں بھی بگاڑ آ جائے گا۔“","",{"t":"نماز ، دوسرے اعمال کے مقبول یا غیر مقبول ہونے کے لیے معیار ہے","k":"رواه الطبراني في ”الأوسط“ ۲/۱۳ من زوائده ، والضياء في ”المختارة“: ۲/۲۰۹، والطبراني\n(الصحيحة: ۱۳۵۸)","e":"حقوق اللہ میں نماز کا اور حقوق العباد میں خون کا محاسبہ سب سے پہلے ہوگا، رہا یہ سوال کہ حساب و کتاب کا سلسلہ اللہ تعالیٰ کے حقوق سے شروع ہوگا یا بندوں کے حقوق سے، تو احادیث مبارکہ کے ظاہری مفاہیم سے تو یہ معلوم ہوتا ہے کہ حقوق اللہ سے ابتدا ہوگی، بہر حال اس معاملے کو اللہ تعالیٰ کے سپرد کر دینا ہی بہتر ہے۔ نماز میں کامیابی مکمل کامیابی کا پیش خیمہ ہے اور نماز میں ناکامی ، مستقل نامرادی کا سبب بن سکتا ہے، ہمیں چاہئے کہ ہم اپنی نمازوں کی حفاظت بھی کریں اور سنت کے مطابق ان کی ادائیگی بھی۔"}],[482,"سیدنا ابو قتادہ بن ربعی رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ نے فرمایا: میں نے تیری امت پر پانچ نمازیں فرض کی ہیں اور اپنے اوپر یہ لازم کیا ہے کہ جو آدمی ان نمازوں کی ان کے اوقات میں محافظت کرے گا، اسے جنت میں داخل کروں گا اور جو ان کی حفاظت نہیں کرے گا اس کو (بخشنے کا ) میرا کوئی معاہدہ نہیں۔“","",{"t":"نماز کی اہمیت","k":"أخرجه ابن ماجه: ۱۴۰۳ ، وابن نصر في ”قيام الليل“: ص ۱۱۳\n(الصحيحة: ۴۰۳۳)","e":"واجبات وفرائض اور مندوبات و مستحبات کی ادائیگی کا خیال رکھتے ہوئے پانچ نمازوں کی ادائیگی عظیم عمل ہے، یہ عمل انسان میں برائیوں سے بچنے کی صلاحیت پیدا کرتا ہے، جیسا کہ ارشادِ باری تعالیٰ ہے: ﴿إِنَّ الصَّلَاةَ تَنْهَى عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ﴾ (سورۂ عنکبوت: ۴۵) ...... ”بیشک نماز بے حیائی اور برائی سے روکتی ہے۔“ اللہ تعالیٰ نے نماز میں ایسی روحانی تاثیر رکھی ہے کہ انسان خود بخود برائیوں سے متنفر ہو جاتا ہے اور پھر اس عمل کی برکت کی وجہ سے اعمال صالحہ کی طرف مائل ہو جاتا ہے۔ ایسا شخص دن بدن جنت کے قریب ہوتا چلا جاتا ہے اور بالآخر اللہ تعالیٰ اس کو بہشت کا وارث بنا دیتے ہیں۔ دوسری طرف بے نماز کے برے انجام کا بیان ہے، بلکہ بے نماز تو کجا، جو آدمی نمازوں کی ( با قاعدگی سے ادائیگی ) محافظت نہیں کرتا، بلکہ بسا اوقات ادا کر لیتا ہے اور بعض اوقات چھوڑ دیتا ہے، وہ اللہ تعالیٰ کے عہد و ضمانت سے خارج ہو جاتا ہے۔"}],[483,"سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”نماز تین حصوں پر مشتمل ہے: ایک تہائی حصہ طہارت ہے، ایک تہائی رکوع اور ایک تہائی سجدے ہیں۔ جس نے کما حقہ نماز ادا کی اس کے بقیہ اعمال بھی مقبول ہوں گے اور جس کی نماز مردود ہو گئی، اس کے بقیہ اعمال بھی رائیگاں جائیں گے۔“","",{"t":"نماز کی اہمیت","k":"أخرجه البزار في ”مسنده“: ۱/۱۷۷/۳۴۹\n(الصحيحة: ۲۵۳۷)","e":"نماز کو دوسرے اعمال کی قبولیت اور تردید کے لیے معیار قرار دیا گیا ہے، جس آدمی نے نماز کے حقوق کا خیال نہ رکھا، اس کے بقیہ اعمالِ صالحہ بھی رائیگاں ہو جاتے ہیں اور جو با قاعدگی کے ساتھ واجبات وفرائض و ارکان کی پاسداری کرتے ہوئے نماز کی ادائیگی کرتا رہا، اس کے باقی اعمال کو بھی شرف قبولیت حاصل ہوگا۔ نیز اس حدیث مبارکہ سے یہ مسئلہ ثابت ہو رہا ہے کہ طہارت اور رکوع و سجود نماز کے اہم ترین ارکان ہیں اور ان کے بغیر کسی صورت میں نماز مقبول نہیں ہوگی، یاد رہے کہ اس حدیث سے تکبیر تحریمہ، قیام، تشہد اور سلام وغیرہ کی فرضیت و اہمیت میں کوئی کمی نہیں آ رہی، اس سے صرف تین ارکان کی اہمیت کو ثابت کیا جارہا ہے کہ طہارت مکمل کر کے نماز میں رکوع و سجود جیسے ارکان اطمینان و اعتدال کے ساتھ ادا کئے جائیں، نہ کہ جلد بازی میں۔"}],[484,"سیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے، نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”جس نے رمضان کے روزے رکھے، پانچوں نمازیں پڑھیں اور بیت اللہ کا حج کیا ۔ راوی کہتا ہے میں نہیں جانتا کہ آپ صلی اللہ علیہ وسلم نے زکاۃ کا ذکر کیا تھا یا نہیں۔ تو اللہ تعالیٰ پر حق ہے کہ اسے معاف کر دے، وہ اللہ کے راستے میں ہجرت کرے یا اپنی جائے پیدائش میں ٹھہرا رہے ۔“ سیدنا معاذ رضی اللہ عنہ نے کہا: کیا میں لوگوں کو (اس حدیث ) کی خبر دے دوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”رہنے دو معاذ! تاکہ وہ ( مزید ) عمل کرتے رہیں۔“","",{"t":"نماز کی اہمیت","k":"أخرجه الترمذي: ۲۵۳۰ ، وأحمد: ۵/۲۳۲ ، ۲۴۰ ، ۲۴۰ ، والبزار: ۱/۲۳/۲۶\n(الصحيحة: ۳۲۲۹)","e":"اس حدیث میں یہ نقطہ موجود ہے کہ جس حدیث کے بیان کرنے سے لوگ عملاً کوتاہی کر سکتے ہوں، یا غلط فہمی اور فکری انتشار میں پڑ سکتے ہوں تو اسے بیان نہ کیا جائے، ہاں اگر سامعین احادیث کی روح اور مقصد کو سمجھنے والے ہوں تو ان کے سامنے وضاحت کی جاسکتی ہے۔ مذکورہ اس حدیث کا مفہوم ہے کہ روزے، نماز اور حج انتہائی افضل اعمال ہیں اور مغفرت الہی کا بہت بڑا سبب ہیں، لیکن اس حدیث کا یہ مطلب ہرگز نہیں کہ ان کے علاوہ باقی ارکانِ اسلام اور اعمالِ صالحہ کو نظر انداز کر دیا جائے۔"}],[485,"ابو مالک اشجعی اپنے باپ طارق بن اشیم سے بیان کرتے ہیں کہ جب کوئی آدمی مسلمان ہوتا تو آپ صلی اللہ علیہ وسلم اسے سب سے پہلے نماز کی تعلیم دیتے تھے۔","",{"t":"نماز کی اہمیت","k":"أخرجه البزار في ”مسنده“ ۱/۱۷۱/۳۳۸ ، وأخرجه الطبراني في ”الكبير“ مختصرا\n(الصحيحة: ۳۰۳۰)","e":"چونکہ مشرف باسلام ہونے کے بعد سب سے پہلا اور اہم فریضہ نماز ہے اور نماز ہی سے کسی آدمی کے مسلمان ہونے یا نہ ہونے کا علم ہوتا ہے، اسی لیے نو مسلم کو سب سے پہلے نماز کی تعلیم دی جاتی ہے۔"}],[486,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے، نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”جو اللہ اور اس کے رسول پر ایمان لایا، نماز قائم کی اور رمضان کے روزے رکھے تو اللہ تعالیٰ پر حق ہے کہ اسے جنت میں داخل کرے، وہ اللہ تعالیٰ کے راستے میں جہاد کرے یا اپنی جائے ولادت میں رہائش پذیر رہے۔“ صحابہ نے کہا: اے اللہ کے رسول! کیا ہم لوگوں کو ( یہ حدیث بیان کر کے خوشخبری نہ سنا دیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ” جنت میں سو درجے ہیں، جنھیں اللہ تعالیٰ نے اپنے راستے میں جہاد کرنے والوں کے لیے تیار کر رکھا ہے، ہر دو درجوں کے درمیان اتنا تفاوت ہے، جتنا آسمان اور زمین کے مابین ہے، جب تم اللہ تعالیٰ سے (جنت کا ) سوال کرو تو جنت الفردوس کا سوال کرو، کیونکہ یہ جنت کا منتخب اور اعلیٰ مقام ہے، ( میرا خیال ہے یہ بھی فرمایا ) اس کے اوپر رحمن کا عرش ہے اور اسی سے جنت کی نہریں پھوٹتی ہیں۔“","",{"t":"نماز کی اہمیت","k":"أخرجه البخاري: ۴/۱۴ و ۹/۱۰۱ ، وابن حبان: ۳/۱۲۲/۱۷۴۴ ، ۷/۶۴/۴۵۹۲ ، ۹/۲۴۲/۷۳۴۷ ، وأحمد: ۲/۳۳۵ و ۳۳۹ ، والبيهقي في ”الأسماء“: ۳۹۸\n(الصحيحة: ۹۲۱)","e":"حدیث اپنے مفہوم میں انتہائی واضح ہے کہ مسلمان کو اپنی نجات کے لیے صرف توحید، نماز اور روزے پر اکتفا نہیں کرنا چاہئے ، بلکہ اللہ تعالیٰ کی طرف سے دوسرے معینہ واجبات و مستحبات کا اہتمام بھی کرنا چاہئے۔ بطور مثال جہاد ہے، کہ جہاد کرنے والوں کے لیے اللہ تعالیٰ نے جنت میں سو درجات تیار کر رکھے ہیں۔ اللہ تعالیٰ ہمیں موقع نصیب فرمائے۔ (آمین)"}],[487,"سیدنا ابو قتیلہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم حجہ الوداع کے موقع پر لوگوں میں کھڑے ہوئے اور فرمایا: ”نہ میرے بعد کوئی نبی آئے گا اور نہ میری امت کے بعد کوئی امت آئے گی ، سو اپنے رب کی عبادت کرو، پانچ نمازیں قائم کرو، زکاۃ ادا کرو، ماہِ ( رمضان ) کے روزے رکھو اور اپنے معاملات کے مسئولوں (یعنی امیروں) کی اطاعت کرو، تم اپنے رب کی جنت میں داخل ہو جاؤ گے۔“","",{"t":"نماز کی اہمیت","k":"أخرجه الطبراني في ”المعجم الكبير“ : ۲۲/۳۱۶/۷۹۷ ، وفي ”مسند الشاميين“: ۲/۱۹۳ - ۱۹۴ ، وأبونعيم في ”معرفة الصحابة“: ۲/۱/۲۸۳ ، وابن مندة في ”المعرفة“ أيضاً: ۲/۱/۱۷۵\n(الصحيحة: ۳۲۳۳)"}],[488,"سیدنا طلحہ بن عبید اللہ رضی اللہ عنہ کہتے ہیں کہ قضاعہ قبیلے کی شاخ ”بلی“ کے دو آدمی تھے، ان میں ایک شہید ہو گیا اور دوسرا اس سے ایک سال بعد فوت ہوا۔ طلحہ رضی اللہ عنہ کہتے ہیں: مجھے خواب آیا کہ جنت کا دروازہ کھولا گیا اور بعد میں فوت ہونے والا شہید ہونے والے سے پہلے جنت میں داخل ہوا، مجھے بڑا تعجب ہوا۔ جب صبح ہوئی تو میں نے اس خواب کا تذکرہ کیا اور بات رسول اللہ صلی اللہ علیہ وسلم تک پہنچا دی، آپ صلی اللہ علیہ وسلم نے فرمایا: ”کیا اس نے (ایک سال پہلے شہید ہونے والے کے بعد) رمضان کے روزے نہیں رکھے اور ایک سال کی (فرض نمازوں کی ) چھ ہزار اور اس سے زائد اتنی اتنی نفل رکعتیں نہیں کیں ؟“","",{"t":"ایک سال کی نمازوں اور روزوں کی بنا پر شہید پر فوقیت","k":"رواه البيهقي في ”الزهد“: ۲/۷۳ ، وأخرج ابن ماجه: ۳۹۲۵ ، وابن حبان: ۲۴۶۶ نحوه، لكن أتم منه - وكذا رواه أحمد: ۱/۱۶۱، ۱۶۳\n(الصحيحة: ۲۵۹۱)","e":"اللہ تعالیٰ کے دین کی سر بلندی کی خاطر جامِ شہادت نوش کرنا عظمتوں والا عمل ہے، جس سے کسی صورت بے رخی اختیار نہیں کی جاسکتی اس حدیث کا مفہوم قطعا یہ نہیں ہے کہ جہاد کو ترک کر دیا جائے، بلکہ اس حدیث سے نماز اور روزوں کی اہمیت کا پتہ چلتا ہے۔ قابل غور بات ہے کہ ایک آدمی شہید ہوا اور دوسرا اس کی شہادت سے ایک سال بعد طبعی موت مر کر جنت میں پہلے پہنچ گیا، اس کی وجہ ایک رمضان کے روزے اور ایک سال کی فرضی و نفلی نمازیں ہیں۔ معلوم یہ ہوا کہ زندگی اللہ تعالیٰ کی امانت ہے، اس میں جس قدر ممکن ہو سکے صوم وصلاۃ اور دیگر اعمال صالحہ سرانجام دیے جائیں اور جب جہاد کی ضرورت پڑے تو مال و جان کو خطرے میں ڈال دینے سے گریز نہ کیا جائے۔ اسلامی مہینہ کبھی (۲۹) دنوں کا ہوتا ہے اور کبھی (۳۰) دنوں کا ، اگر سال کے چھ ماہ (۲۹، ۲۹) دنوں کے اور چھ ماہ (۳۰،۳۰) دنوں کے فرض کر لیے جائیں تو سال کے کل (۳۵۴) دن بنتے ہیں، جبکہ ایک دن میں پانچ فرض نمازوں کی رکعتوں کی تعداد (۱۷) ہے، اس اعتبار سے ایک سال میں فرض نمازوں کی کل (۶۰۱۸) رکعتیں بنتی ہیں، لیکن مہینوں کے دنوں میں (۲۹) یا (۳۰) کی وجہ سے فرق آ سکتا ہے، اس لیے آپ صلی اللہ علیہ وسلم نے (۶۰۰۰) رکعتوں کا ذکر کیا ہے۔"}],[489,"سیدنا حذیفہ رضی اللہ عنہ نے شبث بن ربعی کو (نماز میں ) اپنے سامنے تھوکتے دیکھا تو اسے کہا: شبث ! اپنے سامنے نہ تھوکا کر، کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے ایسا کرنے سے منع کرتے ہوئے فرمایا: ”جب آدمی نماز میں کھڑا ہوتا ہے تو اللہ تعالیٰ اپنے چہرے کے ساتھ اس کی طرف (اس وقت تک ) متوجہ رہتا ہے، جب تک وہ سلام نہیں پھیرتا یا کوئی برا فعل نہیں کرتا۔“","",{"t":"اللہ تعالیٰ کا نمازی کی طرف متوجہ ہونا","k":"أخرجه ابن ماجه: ۱/۳۱۹ - ۳۲۰\n(الصحيحة: ۱۵۹۶)","e":"اس میں نمازی کی قدر و منزلت کا بیان ہے کہ اللہ تعالیٰ بھی اپنا رخ انور اس کی طرف پھیر دیتے ہیں، لیکن شرط یہ ہے کہ وہ ظاہری اور باطنی طور پر یکسوئی اختیار کرے، کیونکہ اللہ تعالیٰ کو بے توجہی اور برائی سے نفرت ہے۔ نیز اس حدیث سے نمازی کو ضرورت کے مطابق تھوکنے کی گنجائش ملتی ہے، اس پر تفصیلی بحث یہ ہے۔ عصر حاضر میں مساجد کی خوبصورت عمارتوں اور ان میں بچھی ہوئی خوبصورت چٹائیوں اور قالینوں کی وجہ سے درج بالا حدیث کو سمجھنے میں دقت پیش آئی ہے۔ یہ احادیث اس وقت بیان کی گئی تھیں، جب مساجد کا فرش نرم مٹی اور ریت پر مشتمل ہوتا تھا اور ان میں بچھانے کے لیے صفیں بھی نہیں ہوتی تھیں۔ در حقیقت مسئلہ یوں ہے کہ بوقت ضرورت مسجد میں تھوکنا جائز ہے، جیسا کہ سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مسجد کی قبلہ والی سمت تھوک دیکھا، جو آپ پر گراں گزرا، بہر حال آپ صلی اللہ علیہ وسلم نے اس کو صاف کیا اور فرمایا : «إِنَّ اَحَدَكُمْ إِذَا قَامَ فِي صَلَاتِهِ فَإِنَّمَا يُنَاجِي رَبَّهُ ، فَلَا يَبْزُقَنَّ فِي قِبْلَتِهِ وَلَكِنْ عَنْ يَسَارِهِ اَوْ تَحْتَ قَدَمِه» (بخاری) ...... ”جب تم میں سے کوئی آدمی نماز میں کھڑا ہوتا ہے تو وہ اپنے رب سے سرگوشی کر رہا ہوتا ہے، اس لیے وہ قبلہ والی سمت نہ تھوکا کرے، البتہ بائیں جانب یا اپنے پاؤں کے نیچے تھوک سکتا ہے۔“ پھر (تیسرا طریقہ بیان کرتے ہوئے) آپ صلی اللہ علیہ وسلم نے اپنی چادر کا کنارہ پکڑا، اس میں تھوکا اور اس کو مل دیا اور فرمایا: ”یا پھر اس طرح کر لیا کرے۔“ اس موضوع پر دلالت کرنے والی کئی احادیث ہیں، لیکن درج ذیل حدیث سے معلوم ہوتا ہے کہ یہ رخصت اس وقت ہے جب آدمی نماز پڑھ رہا ہو اور اسے مجبوراً تھوکنا پڑ جائے۔ سیدنا انس رضی اللہ عنہ ہی بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «الْبُزَاقُ فِي الْمَسْجِدِ خَطِيئَةٌ وَكَفَّارَتُهَا دَفْنُهَا» (بخاری) ...... ”مسجد میں تھوکنا گناہ ہے اور اس کا کفارہ تھوک کو دفن کر دینا ہے۔“ رہا مسئلہ قبلہ والی سمت میں تھوکنے کا، تو وہ بھی منع ہے، جیسا کہ مذکورہ بالا حدیث سے پتہ چلتا ہے، نیز اس موضوع پر کئی دوسری احادیث موجود ہیں۔ بہر حال مساجد کی موجودہ صورتحال کو سامنے رکھتے ہوئے اس رخصت پر عمل کرنے سے گریز کرنا ہی بہتر ہے۔"}],[490,"سیدنا علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں مسواک کرنے کا حکم دیا اور فرمایا: ” جب بندہ نماز میں کھڑا ہوتا ہے تو اس کے پاس ایک فرشتہ آتا ہے اور اس کے پیچھے کھڑے ہو کر قرآن مجید سنتا اور قریب ہوتا رہتا ہے، وہ قرآن مجید سنتے سنتے اتنا قریب ہو جاتا ہے کہ اپنا منہ اس کے منہ پر رکھ دیتا ہے اور نمازی جو آیت بھی پڑتا ہے فرشتہ اسے اپنے اندر سما لیتا ہے۔“","",{"t":"فرشتوں کا نمازی کی تلاوت سننے کا انداز","k":"رواه البيهقي في ”السنن الكبرى“ ۱/۳۸ ، والضياء في ”المختارة“ ۱/۲۰۱، والبزار في ”مسنده“: ص ۶۰\n(الصحيحة: ۱۲۱۳)","e":"جہاں نوری مخلوق کا ذکر الہی کے ساتھ گہرا تعلق ہے، وہاں ذکر کرنے والے بھی ان کے نور منظور نظر ہیں۔ فرشتے خود بھی کثرت سے ذکر کرتے ہیں اور ذکر کرنے والے انسانوں سے محبت بھی کرتے ہیں، جیسا کہ سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «إِنَّ لِلَّهِ تَعَالَى مَلَائِكَةٌ يَطُوْفُوْنَ فِي الطُّرُقِ يَلْتَمِسُونَ أَهْلَ الذِكْرِ ، فَإِذَا وَجَدُوْا قَوْمًا يَذْكُرُونَ اللَّهَ عَزَّ وَجَلَّ، تَنَادَوْا: هَلُمُّوا إِلَى حَاجَتِكُمْ، فَيَحُفُونَهُمْ بِأَجْنِحَتِهِمْ إِلَى السَّمَاءِ الدُّنْيَا» (بخاری، مسلم) ...... ”اللہ تعالیٰ کے کچھ فرشتے ایسے ہیں جو راستوں میں ذکر کرنے والوں کی تلاش میں رہتے ہیں، جب وہ ایسے لوگوں کو پالیتے ہیں جو اللہ تعالیٰ کا ذکر کر رہے ہوتے ہیں تو ایک دوسرے کو پکارتے ہوئے کہتے ہیں: اپنے مقصد کی طرف آجاؤ۔ پھر انھیں آسمان دنیا تک اپنے پروں سے گھیر لیتے ہیں ...... “ نمازی میں اس امر کی رغبت ہونی چاہئے کہ وہ نماز میں زیادہ سے زیادہ تلاوت کرے، حدیث مبارکہ کا سیاق بھی اس حقیقت کی غمازی کر رہا ہے کہ یہ سعادت اس آدمی کو نصیب ہوتی ہے جو نماز میں طویل قرائت کرے۔ مسلمانوں کو چاہیے کہ وہ فرشتوں کے اظہار محبت کو سمجھیں اور سلسلہ نماز میں خواہ مخواہ کی غفلت کرنے سے باز رہیں۔ نمازی کو پیاز اور لہسن وغیرہ کھا کر مسجد میں آنے سے منع کیا گیا۔ اس سے معلوم ہوتا ہے کہ نمازی کو منہ کی خوب صفائی کرنی چاہیے، نیز اس کے جسم اور لباس سے کسی قسم کی بدبو نہیں آنی چاہیے، تا کہ اسے اس حدیث میں بیان کی گئی سعادت نصیب ہو سکے۔"}],[491,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم کو کسی آدمی کا طرز وطریقہ پسند آتا تو آپ اسے نماز کا حکم دیتے تھے۔","",{"t":"نیکی کی رغبت پر نماز کا حکم","k":"أخرجه البخاري في ”التاريخ“: ۱/۱/۱۸۰ ، والبزار: ۱/۳۴۵/۷۱۶، وأبو نعيم في ”الحلية“: ۱/۳۴۳، والخطيب: ۴/۳۶۰\n(الصحيحة: ۲۹۵۳)","e":"امام البانی رحمہ اللہ لکھتے ہیں : جو بات مجھے سمجھ آرہی ہے کہ ”نحو الرجل“ (طرز وطریقہ) سے مراد اس آدمی کا خیر و بھلائی اور زہد و عبادت کی طرف متوجہ ہونا ہے، جب آپ صلی اللہ علیہ وسلم کو اس کی رغبت کا اندازہ ہوتا تو اسے نفلی نماز کی ادائیگی کی تلقین کرتے ، کیونکہ نماز سے اللہ تعالیٰ کے ساتھ تعارف میں اضافہ ہوتا ہے۔ امام ہیثمی نے اس حدیث کو رات کی نماز کے باب میں درج کر کے یہ اشارہ کیا ہے کہ اس کا تعلق نفلی نماز سے ہے۔ (صحیحہ: ۲۹۵۳) چونکہ نماز خصائل حمیدہ اور صفات حسنی کی بنیاد ہے اور برائیوں سے روکنے والی ہے، جس آدمی میں نیکی کی رغبت پائی جاتی ہو تو وہ سب سے زیادہ اس بات کا مستحق ہے کہ نماز ادا کرے، تاکہ اس کی صفاتِ حسنہ محفوظ رہ سکیں، وگرنہ سرے سے ان کے مفقود ہو جانے کا یا ان کے اجر و ثواب کے ضائع ہونے کا مکمل خطرہ ہوگا۔"}],[492,"سیدنا ابو ذر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم میں سے ہر شخص کے ہر عضو پر صدقہ (واجب) ہے، ہر مرتبہ ”سبحان اللہ“ کہنا صدقہ ہے اور ہر مرتبہ ”الحمد للہ“ کہنا صدقہ ہے، ہر مرتبہ ”لا الہ الا اللہ“ کہنا صدقہ ہے اور ہر مرتبہ ”اللہ اکبر“ کہنا صدقہ ہے، نیکی کا حکم دینا صدقہ ہے اور برائی سے روکنا صدقہ ہے اور ان سب سے وہ دو رکعتیں کافی ہو جائیں گی جو کوئی شخص چاشت کے وقت ادا کرے گا۔“","",{"t":"نماز، جسم کے جوڑوں کا ٹیکس ادا کرنے کا بہترین ذریعہ ہے","k":"أخرجه مسلم: ۲/۱۵۸ ، وأبو داود: ۲/۲۵۹ ، وأحمد: ۵/۱۶۷ ، ۱۶۸\n(الصحيحة: ۵۷۷)","e":"دوسری احادیث میں وضاحت کر دی گئی ہے کہ اللہ تعالیٰ نے ایک انسان کو تین سو ساٹھ (۳۶۰) جوڑ عطا کیے ہیں۔ غور کرنا چاہئے کہ جوڑ اللہ تعالیٰ کی کتنی بڑی نعمت ہے، اگر ہڈیوں کے جوڑ سلب کر لیے جائیں تو انسان کا جینا دوبھر ہو جائے گا، کھانے پینے کے معاملے میں اس کا انحصار دوسروں پر ہوگا، قضائے حاجت کے معاملہ میں وہ کسی کا محتاج ہو گا، چلن پھرن، اٹھک بیٹھک، غرضیکہ وہ ہر چیز میں دوسروں کی نظر کرم اور دست شفقت کا منتظر ہو گا۔ لیکن کیا ہم ان عظیم نعمتوں کا شکر یہ ادا کر رہے ہیں یا دن بدن اللہ تعالیٰ کے مقروض بنتے جا رہے ہیں؟ صرف دو رکعتوں سے ۳۶۰ جوڑوں کا ٹیکس ادا ہو جاتا ہے۔"}],[493,"یوسف بن عبد اللہ بن سلام کہتے ہیں: میں سیدنا ابو دردا رضی اللہ عنہ کے پاس اس وقت آیا جب وہ مرض الموت میں مبتلا تھے۔ انھوں نے مجھے کہا: اے میرے بھتیجے! کون سا ارادہ یا ضرورت تجھے اس شہر میں لے آئی ہے؟ میں نے کہا: کوئی مقصد نہیں، سوائے اس کے کہ آپ کے اور میرے والد عبداللہ بن سلام کے مابین ایک تعلق تھا، (اس کی بنا پر آیا ہوں)۔ ابو دردا رضی اللہ عنہ نے کہا: اگر اس وقت جھوٹ بولوں تو بہت برا ہے، میں نے تو رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”جو آدمی وضو کرے اور اچھا وضو کرے، پھر دو یا چار رکعتیں پڑھے اور ان میں اچھے انداز میں ذکر و اذکار اور خشوع و خضوع کرے، پھر بخشش طلب کرے تو اس کو بخش دیا جائے گا۔“ رکعات کی تعداد کے بارے میں سہیل راوی کو شک ہوا۔","",{"t":"اچھے انداز میں ادا کی گئی نماز کا صلہ","k":"أخرجه أحمد في ”المسند“: ۶/۴۵۰\n(الصحيحة: ۳۳۹۸)","e":"ایسی نماز کو نماز توبہ کہا جا سکتا ہے، اس کی مزید وضاحت اس حدیث سے ہو رہی ہے: سیدنا ابوبکر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب آدمی سے گناہ ہو جاتا ہے اور وہ (اس کے ازالہ کے لیے ) وضو کر کے نماز پڑھتا ہے، اور پھر اللہ تعالیٰ سے بخشش طلب کرتا ہے تو اللہ تعالیٰ اس کا گناہ بخش دیتے ہیں۔“ پھر آپ صلی اللہ علیہ وسلم نے اس آیت کی تلاوت کی: ﴿وَالَّذِينَ إِذَا فَعَلُوا فَاحِشَةً أَوْ ظَلَمُوا أَنْفُسَهُمْ ذَكَرُوا اللَّهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ وَمَنْ يَغْفِرُ الذُّنُوبَ إِلَّا اللهُ وَلَمْ يُصِرُّوا عَلَى مَا فَعَلُوا وَهُمْ يَعْلَمُونَ﴾ (سورۂ آل عمران: ۱۳۵) ...... ”جو لوگ برائی کرنے یا اپنے آپ پر ظلم کرنے کے بعد اللہ تعالیٰ کا ذکر کرتے ہیں اور اپنے گناہوں کی بخشش طلب کرتے ہیں اور اللہ ہی ہے جو گناہوں کو بخشتا ہے اور وہ اپنے (برے) کیے پر اصرار نہیں کرتے اور وہ جانتے ہیں۔ (ترمذی: ۴۹۶، ۳۰۰۶، ابوداود: ۱۵۲۱، ابن ماجہ: ۱۳۹۵)"}],[494,"سیدنا عبد اللہ بن عمر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے نشے میں مدہوش ہو کر ایک نماز ترک کر دی، گویا کہ پوری دنیا اور جو کچھ اس پر ہے اس کا تھا، جو اس سے چھین لیا گیا اور جس نے نشے میں مدہوش ہونے کی وجہ سے چار دفعہ نماز ترک کر دی، تو اللہ تعالیٰ پر حق ہے کہ اسے ”طِینَةُ الْخَبَال“ پلائے۔“ کہا گیا کہ اے اللہ کے رسول! ”طِینَةُ الْخَبَال“ کسے کہتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جہنمیوں کے پیپ کو“۔","",{"t":"نماز ترک کرنے کا وبال","k":"أخرجه الحاكم: ۴/۱۴۶ ، وأحمد: ۲/۱۷۸ - والسياق له ، والبيهقي في ”السنن الكبرى“: ۱/۳۸۹ ، و ”شعب الأيمان“: ۵/۸/۵۵۸۲\n(الصحيحة: ۳۴۱۹)","e":"آج کل نماز ترک کر دینے کی بیماری عام ہے، بالخصوص نوجوان طبقہ، جو دن بدن غافل ہوتا چلا جا رہا ہے، اگر یہ لوگ عقل کے ناخن لیں تو اس حدیث میں بیان کی گئی وعید کافی ہے۔ سیدنا عبد اللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «اجْتَنِبُوا الْخَمْرَ، فَإِنَّهَا مِفْتَاحُ كُلِّ شَرٍّ» (حاکم: ۴/۱۴۵، صحیحہ: ۲۷۹۸) ...... ”شراب سے بچتے رہو، یہ تو ہر برائی کا سرچشمہ ہے۔“ ہم ظاہر پرست ہیں، اس لیے نبی کریم صلی اللہ علیہ وسلم نے ہمیں سمجھانے کے لیے غیر محسوس چیز کو محسوس انداز میں بیان کیا کہ فرض کریں دنیا اور اس کے تمام خزانے ایک آدمی کی ملکیت ہوں اور وہ اس سے چھین لیے جائیں تو اس پر کیا بیتے گی؟ وہ کتنا پریشان ہو گا ؟ کیا اس کے دل و دماغ ٹھکانے پر رہیں گے؟ کیا وہ دنیا میں زندہ رہنے کے قابل رہے گا ؟ کیا اس کے قرابتدار اسے اچھے لگیں گے؟ ہر گز نہیں، کسی صورت میں نہیں۔ لیکن جب وہ ایک نماز چھوڑتا ہے تو اس کا نقصان اس سے کہیں زیادہ ہو جاتا ہے، لیکن کیا اس کی روح اس قدر پاک اور قوی ہے کہ وہ اس نقصان کو بھی محسوس کرے؟ سگریٹ، نسوار، ہیروئن، افیون، بھنگ، چرس اور شراب سب ایک ہی دریا سے پھوٹنے والی نہریں ہیں، جو کم از کم انسانی ذہن کے توازن کو برقرار نہیں رہنے دیتیں۔ اللہ تعالیٰ کی خاطر اور اپنی ذات کا لحاظ کرتے ہوئے اپنے منہ اور وجود کو ان خباثتوں سے پاک رکھنا چاہئے۔"}]])